def test_clock_port_and_critical_contexts(tmp_path):
    compiler=shutil.which('gcc')
    if compiler is None:pytest.skip('Host GCC unavailable')
    for p,b in NativeClock_FilesRender(hclk_hz=72_000_000).items():
