{assert(d==&hUsbDeviceFS && n==7U && p!=NULL);sent++;return USBD_OK;}
static USBD_StatusTypeDef USBD_CtlPrepareRx(USBD_HandleTypeDef *d,uint8_t *p,uint16_t n)
{assert(d==&hUsbDeviceFS && n==7U);armed=p;return USBD_OK;}
