    root, args = native
    proof, inventory, files = NativeClassicCdc_Inspect(root, **args)
    original_contract = NativePlatformContract_Inspect(files, proof, inventory)
    irq = original_contract['dio1_irq']['handler'].replace('_IRQHandler','_IRQn')
