        'USBD_CDC_TransmitPacket','USBD_CDC_ReceivePacket','USBD_CDC_SetTxBuffer','USBD_CDC_SetRxBuffer']
    if 'NativeCdc_Fault' in derived:
        names = ['NativeCdc_Fault','NativeCdc_InitAbort','NativeCdc_Open']+names
    functions = []
