def MissionRadioProfileMacros_Render(model: ProjectModel) -> str:
    import struct
    from silverstar_fccg.project.radio_variants import FlightRadioConfiguration_Get
    active = model.DeviceInstance_Get(model.air_link.flight_radio_instance)
    power = FlightRadioConfiguration_Get(model, active)[1] if active is not None else model.flight_tx_power_dbm
    link = model.air_link
    if link.radio_family == "nrf24":
        from silverstar_fccg.project.nrf24 import Nrf24Link_Validate
        config = Nrf24Link_Validate(link)
        profile = bytes([1, 1, 14, 0, (link.frequency_hz - 2400000000) // 1000000,
            {250: 0, 1000: 1, 2000: 2}[config["data_rate_kbps"]], power & 255]) + bytes.fromhex(config["address"]) + bytes([
            config["retry_delay_us"] // 250 - 1, config["retry_count"], 2, 32, link.packet_mtu, 1])
        schema = 3
    else:
        # Historical little-endian SX schema2 profile, exactly15 bytes.
        profile = struct.pack("<IBIBHHb", link.frequency_hz, link.spreading_factor,
            link.bandwidth_hz, int(link.coding_rate[-1]), link.preamble_symbols, link.packet_mtu, power)
        schema = 2
    values = ",".join(f"0x{value:02X}U" for value in profile)
    return f"#define MISSION_RADIO_SNAPSHOT_SCHEMA {schema}U\n#define MISSION_RADIO_PROFILE_BYTE_COUNT {len(profile)}U\n#define MISSION_RADIO_PROFILE_BYTES {{{values}}}\n"


def AirLinkHeader_Render(model: ProjectModel, *, target: str = "flight") -> str:
    if model.air_link.radio_family == "nrf24":
        from silverstar_fccg.project.nrf24 import Nrf24Header_Render
        return Nrf24Header_Render(model, target)
    from silverstar_fccg.project.radio_variants import (
        RADIO_PLUGIN, FlightRadioConfiguration_Get, RadioInstanceMacros_Render,
    )
    variant_macros = ""
    output_power = model.ground_target.tx_power_dbm
    if target == "flight":
        active = model.DeviceInstance_Get(model.air_link.flight_radio_instance)
        output_power = FlightRadioConfiguration_Get(model, active)[1] if active is not None else model.flight_tx_power_dbm
        variant_macros = RadioInstanceMacros_Render([
            FlightRadioConfiguration_Get(model, instance) for instance in model.device_instances
            if instance.plugin == RADIO_PLUGIN
        ])
    link = model.air_link
    bandwidths = {200000: "LORA_BW_0200", 400000: "LORA_BW_0400", 800000: "LORA_BW_0800", 1600000: "LORA_BW_1600"}
    coding_rates = {"4/5": "LORA_CR_4_5", "4/6": "LORA_CR_4_6", "4/7": "LORA_CR_4_7", "4/8": "LORA_CR_4_8"}
    if link.spreading_factor not in range(5, 13) or link.bandwidth_hz not in bandwidths or link.coding_rate not in coding_rates:
        raise ValueError("AIR Link SX128x PHY parameters are unsupported")
    if link.preamble_symbols != 16 or link.header_mode != "explicit" or not link.crc_enabled or link.iq_mode != "normal":
        raise ValueError("The current SX128x driver supports the qualified explicit/CRC/normal-IQ profile")
    return f"""#ifndef __AIR_LINK_CONFIG_H
#define __AIR_LINK_CONFIG_H

/* Shared SilverStar AIR Link snapshot; AIR M0 remains a separate wire protocol. */
#define AIR_LINK_FREQUENCY_HZ {link.frequency_hz}UL
#define AIR_LINK_TX_POWER_DBM {output_power}
#define AIR_LINK_SPREADING_FACTOR {link.spreading_factor}U
#define AIR_LINK_BANDWIDTH_HZ {link.bandwidth_hz}UL
#define AIR_LINK_CODING_RATE_DENOMINATOR {int(link.coding_rate[-1])}U
#define AIR_LINK_SX128X_SF LORA_SF{link.spreading_factor}
#define AIR_LINK_SX128X_BW {bandwidths[link.bandwidth_hz]}
#define AIR_LINK_SX128X_CR {coding_rates[link.coding_rate]}
#define AIR_LINK_PREAMBLE_SYMBOLS {link.preamble_symbols}U
#define AIR_LINK_SX128X_PREAMBLE_ENCODED 0x18U
#define AIR_LINK_SX128X_HEADER LORA_PACKET_VARIABLE_LENGTH
#define AIR_LINK_SX128X_CRC LORA_CRC_ON
#define AIR_LINK_SX128X_IQ LORA_IQ_NORMAL
#define AIR_LINK_PACKET_MTU {link.packet_mtu}U

{variant_macros}#endif /* __AIR_LINK_CONFIG_H */
"""


def MetadataFiles_Render(
    model: ProjectModel, catalog: PluginCatalog, graph: SourceGraph,
    *, component_provenance: dict[str, Any] | None = None,
) -> dict[str, bytes]:
    render_model = deepcopy(model)
    environment = catalog.Component_Get(render_model.development_environment)
    if environment.environment is None or environment.environment.renderer != "vscode_eide_gcc":
        raise ValueError("Selected development environment has no trusted renderer")
    render_model.component_provenance = deepcopy(component_provenance) if component_provenance is not None else {
        component_id: ComponentProvenance_Get(catalog, component_id)
        for component_id in render_model.ComponentIds_Get()
    }
    decoder_profile = (
        LogDecoderProfile_Render(render_model, catalog)
        if render_model.protocols.get("logging") is not None
        else None
    )
    render_model.log_decoder_profile = (
        decoder_profile.Reference_Get()
        if decoder_profile is not None
        else LogDecoderProfileReference()
    )
    project_data = render_model.Dictionary_Get()
    # Ownership is serialized with sorted keys. A preserved provenance entry
    # therefore has a different insertion order from a new catalog entry.
    # Canonicalize this nested field on the first save too, so an unchanged
    # second generation preserves both the descriptor and its ownership hash.
    project_data["component_provenance"] = json.loads(json.dumps(
        project_data["component_provenance"], sort_keys=True
    ))
    project_json = json.dumps(
        project_data, ensure_ascii=False, indent=2, sort_keys=False
    ) + "\n"
    files = {
        "SilverStar.ssproject": project_json,
        ".fccg/hardware-preparation.json": HardwarePreparationMetadata_Render(
            render_model, catalog
        ),
        "SilverStar_Configuration.md": _Configuration_Render(render_model, catalog, graph),
        "Makefile": _Makefile_Render(render_model),
        f"Targets/{render_model.build.target_profile}/target.mk": _TargetManifest_Render(
            render_model, catalog, graph
        ),
        ".vscode/tasks.json": _VsCodeTasks_Render(render_model),
        ".vscode/settings.json": _VsCodeSettings_Render(environment),
        ".vscode/extensions.json": _VsCodeExtensions_Render(environment),
        ".eide/eide.yml": _Eide_Render(render_model, graph, environment),
        ".eide/files.options.yml": _EideFileOptions_Render(environment),
        "Flight_Controller.code-workspace": _VsCodeWorkspace_Render(
            render_model, environment
        ),
        "README.md": _GeneratedReadme_Render(render_model),
    }
    if decoder_profile is not None:
        files.update(
            {
                "Logs/README.md": _GeneratedLogsReadme_Render(render_model),
                "Logs/Golden/expected.json": _GoldenExpected_Render(
                    render_model, decoder_profile
                ),
                decoder_profile.relative_path: decoder_profile.content,
            }
        )
    return {
        name: content if isinstance(content, bytes) else content.encode("utf-8")
        for name, content in files.items()
    }


def _GeneratedModule_Render(model: ProjectModel) -> str:
    sources = [
        "Generated/Src/platform_resources.c",
        "Generated/Src/project_capability_routes.c",
        "Generated/Src/project_device_instances.c",
        "Generated/Src/project_resources.c",
    ]
    if model.protocols.get("logging") is not None:
        sources.extend(
            (
                "Generated/Src/project_log_config.c",
                "Generated/Src/project_log_decoder_profile.c",
