    return (
        "# AUTO-GENERATED BY SILVERSTAR_FCCG. DO NOT EDIT.\n"
        "BUILD_MANIFESTS += Generated/module.mk\n\n"
        "C_SOURCES += \\\n"
        f"{source_lines}\n\n"
