    model: ProjectModel, catalog: PluginCatalog
) -> str:
    catalog = catalog.ProjectView_Get(model)
    definitions: list[tuple[str, str]] = [
        (
            "SILVERSTAR_PROTOCOL_TELEMETRY_ENABLED",
            "1U" if model.protocols.get("telemetry") is not None else "0U",
        ),
        (
            "SILVERSTAR_PROTOCOL_MAINTENANCE_ENABLED",
            "1U" if model.protocols.get("maintenance") is not None else "0U",
        ),
        (
            "SILVERSTAR_PROTOCOL_LOGGING_ENABLED",
            "1U" if model.protocols.get("logging") is not None else "0U",
        ),
    ]
    definitions.extend(_DeviceRuntimeDefaults_Get(model, catalog))
    if model.build.compact_mode:
        power_available = any(entry.get("class") == "SYSTEM_DEVICE_CLASS_POWER"
                              for entry in _DeviceDescriptorEntries_Get(model, catalog))
        definitions.extend((
            ("SYSTEM_USER_POWER_ENABLE", "1U" if power_available else "0U"),
            ("SYSTEM_BUILD_POWER_IMPLEMENTATION_AVAILABLE", "1U" if power_available else "0U"),
        ))
    if model.build.feature_tier == "compact":
        # Reviewed lightweight default; owned START records retain full geometry.
        # Ordinary queue loss remains diagnosed and is not a durability ACK.
        definitions.extend((("SYSTEM_LOG_RECORD_QUEUE_DEPTH", "56U"),
                            ("SYSTEM_LOG_ESTIMATOR_QUEUE_DEPTH", "16U")))
    if model.build.feature_tier == "minimal":
        descriptors = _DeviceDescriptorEntries_Get(model, catalog)
        algorithm_count = sum(len(catalog.Component_Get(component).metadata.get(
            "algorithm_descriptors", [])) for component in model.ComponentIds_Get())
        snapshot_slots = 1 + len(descriptors) + algorithm_count + len(model.logging_streams)
        if model.build.logging_profile == "sf6_minimal":
            definitions.extend((("SYSTEM_LOG_RECORD_SLOT_SIZE", "168U"),
                                ("SYSTEM_LOG_ESTIMATOR_SLOT_SIZE", "96U")))
        definitions.extend((
            ("PROJECT_SYSTEM_CONFIG_SNAPSHOT_SLOTS", f"{snapshot_slots}U"),
            # Owned startup snapshots drain independently of the ordinary queue.
            # This is the authorized Minimal-tier default, independent of MCU.
            ("SYSTEM_LOG_RECORD_QUEUE_DEPTH", "24U"),
            ("SYSTEM_LOG_ESTIMATOR_QUEUE_DEPTH", "16U"),
            ("SYSTEM_LOG_AGGREGATION_BUFFER_SIZE", "1024U" if model.build.logging_profile == "sf6_minimal" else "2048U"),
            ("SYSTEM_IMU_SAMPLE_BUS_DEPTH", "16U"),
            ("ESTIMATOR_BUS_DEPTH", "16U"),
            ("SYSTEM_BUILD_GNSS_ORIGIN_AVAILABLE", "1U" if any(
                "gnss.position" in catalog.InstanceComponent_Get(instance).provides
                for instance in model.device_instances) else "0U"),
            ("SYSTEM_BUILD_GNSS_ORIGIN_STORAGE_SAMPLES", "SYSTEM_ESTIMATOR_GNSS_ORIGIN_WINDOW_SAMPLES" if any(
                "gnss.position" in catalog.InstanceComponent_Get(instance).provides
                for instance in model.device_instances) else "1U"),
        ))
    if model.hardware.mode == "custom" and model.mcu_family == "silverstar.mcu_family.stm32f1_flight":
        gpio_indices = [int(resource.metadata["logical_index"])
                        for resource in model.hardware.resources
                        if resource.kind.startswith("gpio_")]
        definitions.append(("SILVERSTAR_PLATFORM_GPIO_CONTEXT_COUNT",
                            f"{max(gpio_indices, default=0) + 1}U"))
    landing_id = model.strategies.get("landing")
    if landing_id:
        landing_defines = [value.partition("=")[2]
                           for value in catalog.Component_Get(landing_id).build.defines
                           if value.startswith("SYSTEM_BUILD_LANDING_MODE=")]
        if len(landing_defines) != 1:
            raise ValueError("Landing strategy must select one build mode")
        definitions.append(("SYSTEM_BUILD_LANDING_MODE", landing_defines[0]))
    observation_capabilities = {
        capability
        for instance in model.device_instances
        for capability in catalog.InstanceComponent_Get(instance).provides
    }
    observation_mask = (
        (0x03 if "gnss.position" in observation_capabilities else 0) |
        (0x0C if "gnss.velocity" in observation_capabilities else 0) |
        (0x10 if "barometer.altitude" in observation_capabilities else 0)
    )
    definitions.append(("SYSTEM_FUSION_CONFIGURED_MASK", f"0x{observation_mask:02X}U"))
    # Only GNSS constrains horizontal navigation. Barometer-only fusion
    # remains dead reckoning for overall horizontal health.
    definitions.append(("SYSTEM_FUSION_REQUIRED_HEALTH_MASK",
                        f"0x{observation_mask & 0x0F:02X}U"))
    alignment_selected = ["SYSTEM_ALIGNMENT_SOURCE_MASK_ATTITUDE"]
    if observation_mask & 0x03:
        alignment_selected.append("SYSTEM_ALIGNMENT_SOURCE_MASK_GNSS_ORIGIN")
    if observation_mask & 0x10:
        alignment_selected.append("SYSTEM_ALIGNMENT_SOURCE_MASK_BARO_ORIGIN")
    definitions.append(("SYSTEM_USER_ALIGNMENT_SELECTED_MASK",
                        "(" + " | ".join(alignment_selected) + ")"))
    alignment_required = ["SYSTEM_ALIGNMENT_SOURCE_MASK_ATTITUDE"]
    if observation_mask & 0x10:
        alignment_required.append("SYSTEM_ALIGNMENT_SOURCE_MASK_BARO_ORIGIN")
    definitions.append(("SYSTEM_USER_ALIGNMENT_REQUIRED_MASK",
                        "(" + " | ".join(alignment_required) + ")"))
    # A sole independent barometer also needs bounded runtime recovery. A
    # JY901B-only companion remains owned by the locked IMU transport.
    definitions.append(("SYSTEM_BUILD_BAROMETER_COLD_ENABLED", "1U" if any(
        entry["class"] == "SYSTEM_DEVICE_CLASS_BAROMETER" and
        "SYSTEM_DESCRIPTOR_FLAG_SHARED_PHYSICAL" not in str(entry.get("flags", ""))
        for entry in _DeviceDescriptorEntries_Get(model, catalog)
    ) else "0U"))
    # Instance-selected flags retain inactive transports as compile-time zero.
    # They describe existing declarative variants, never new hardware resources.
    instance_symbols: set[str] = set()
    active_instance_symbols: set[str] = set()
    for manifest in catalog.Type_Get("device"):
        symbols = manifest.metadata.get("instance_feature_symbols", [])
        if not isinstance(symbols, list) or not all(
            isinstance(symbol, str) and re.fullmatch(r"[A-Z][A-Z0-9_]*", symbol)
            for symbol in symbols
        ):
            raise ValueError("Device instance feature symbols are invalid")
        instance_symbols.update(symbols)
    for instance in model.device_instances:
        manifest = catalog.InstanceComponent_Get(instance)
        symbols = manifest.metadata.get("active_instance_feature_symbols", [])
        if not isinstance(symbols, list) or not all(
            isinstance(symbol, str) and symbol in instance_symbols for symbol in symbols
        ):
            raise ValueError("Active instance feature symbols are undeclared")
        active_instance_symbols.update(symbols)
    definitions.extend(
        (symbol, "1U" if symbol in active_instance_symbols else "0U")
        for symbol in sorted(instance_symbols)
    )
    definitions.extend(_AlignmentDefinitions_Get(model))
    telemetry_tag = b"\0" * 8
    telemetry_selection = model.protocols.get("telemetry")
    if telemetry_selection is not None:
        telemetry_manifest = catalog.Component_Get(
            telemetry_selection.component
        )
        declared_tag = telemetry_manifest.metadata.get(
            "log_compatibility_tag", ""
        )
        if not isinstance(declared_tag, str):
            raise ValueError("Telemetry log compatibility tag must be text")
        try:
            telemetry_tag = declared_tag.encode("ascii")
        except UnicodeEncodeError as error:
            raise ValueError(
                "Telemetry log compatibility tag must be ASCII"
            ) from error
        if len(telemetry_tag) != 8:
            raise ValueError(
                "Telemetry log compatibility tag must contain eight bytes"
            )
    definitions.append(
        (
            "SILVERSTAR_LOG_TELEMETRY_COMPATIBILITY_TAG",
            "{" + ", ".join(f"0x{value:02X}U" for value in telemetry_tag) + "}",
        )
    )
    selected_components = set(model.ComponentIds_Get())
    feature_symbols: dict[str, bool] = {}
    for manifest in catalog.All_Get():
        raw_symbols = manifest.metadata.get("build_feature_symbols", [])
        if not isinstance(raw_symbols, list) or not all(
            isinstance(symbol, str) for symbol in raw_symbols
        ):
            raise ValueError(
                f"Component {manifest.component_id} build_feature_symbols is invalid"
            )
        for symbol in raw_symbols:
            if re.fullmatch(r"[A-Z][A-Z0-9_]*", symbol) is None:
                raise ValueError(
                    f"Component {manifest.component_id} build feature symbol is invalid"
                )
            feature_symbols[symbol] = feature_symbols.get(symbol, False) or (
                manifest.component_id in selected_components
            )
    # A project view merges source sets for repeated device plugins, while
    # retaining the first instance's metadata. Enable global features from
    # every concrete variant so S->B and B->S have identical feature flags.
    for instance in model.device_instances:
        manifest = catalog.InstanceComponent_Get(instance)
        raw_symbols = manifest.metadata.get("build_feature_symbols", [])
        if not isinstance(raw_symbols, list) or not all(
            isinstance(symbol, str) and re.fullmatch(r"[A-Z][A-Z0-9_]*", symbol)
            for symbol in raw_symbols
        ):
            raise ValueError(
                f"Device {manifest.component_id} build_feature_symbols is invalid"
            )
        for symbol in raw_symbols:
            feature_symbols[symbol] = True
    definitions.extend(
        (symbol, "1U" if enabled else "0U")
        for symbol, enabled in sorted(feature_symbols.items())
    )
    selected_devices = set(model.DevicePluginIds_Get())
    indicator_symbols: dict[str, str] = {}
    for manifest in catalog.Type_Get("device"):
        symbol = manifest.metadata.get("indicator_enable_symbol")
        if not isinstance(symbol, str) or not symbol:
            continue
        if re.fullmatch(r"[A-Z][A-Z0-9_]*", symbol) is None:
            raise ValueError("Indicator enable symbol is invalid")
        value = "1U" if manifest.component_id in selected_devices else "0U"
        previous = indicator_symbols.setdefault(symbol, value)
        if previous != value:
            raise ValueError(f"Indicator enable symbol is ambiguous: {symbol}")
    definitions.extend(sorted(indicator_symbols.items()))
    for component_id in model.base_components:
        manifest = catalog.Component_Get(component_id)
        selection = manifest.selection
        if selection is None or selection.kind.value != "mode":
            continue
        selected = model.modes.get(selection.slot, [])
        if selection.aggregate_symbol:
            symbols = [
                selection.option_symbols[option]
                for option in selected
                if option in selection.option_symbols
            ]
            definitions.append(
                (
                    selection.aggregate_symbol,
                    f"({' | '.join(symbols)})" if symbols else "0U",
                )
            )
        slot_values = model.mode_parameters.get(selection.slot, {})
        for option, parameters in selection.parameters.items():
            values = slot_values.get(option, {})
            for parameter in parameters:
                value = values.get(parameter.parameter_id, parameter.default)
                definitions.append(
                    (
                        parameter.generated_symbol,
                        _GeneratedNumber_Render(
                            value,
                            value_type=parameter.value_type,
                            scale=parameter.generated_scale,
                        ),
                    )
                )
    rows = "\n".join(
        f"#ifndef {symbol}\n"
        f"#define {symbol:<48} {value}\n"
        f"#endif"
        for symbol, value in definitions
    )
    includes = '#include "project_algorithm_parameters.h"\n#include "project_device_build_capabilities.h"'
    early_rows = ("#define SILVERSTAR_COMPACT_MODE 1\n#define AIR_LINK_HAL_BUFFER_SIZE 260\n\n" + rows + "\n\n" + includes) if model.build.compact_mode else includes
    late_rows = "" if model.build.compact_mode else rows
    return f"""#ifndef __PROJECT_FLIGHT_CONFIG_H
#define __PROJECT_FLIGHT_CONFIG_H

{early_rows}

{AUTOGEN_C_COMMENT}

{late_rows}

#if (SYSTEM_USER_MAGNETOMETER_ENABLE != 0U)
#error "Magnetometer selection is deferred in the first SCG release"
#endif

#if ((SILVERSTAR_PROTOCOL_TELEMETRY_ENABLED != 0U) && \
     (SYSTEM_USER_TELEMETRY_ENABLE == 0U))
#error "Telemetry Protocol requires a selected telemetry transport Device"
#endif

#if ((SILVERSTAR_PROTOCOL_MAINTENANCE_ENABLED != 0U) && \
     (SYSTEM_USER_CONSOLE_ENABLE == 0U))
#error "Maintenance Protocol requires the auto-managed console transport"
#endif

#if ((SILVERSTAR_PROTOCOL_LOGGING_ENABLED != 0U) && \
     (SYSTEM_USER_LOG_SINK_ENABLE == 0U))
#error "Logging Protocol requires a selected physical Log Sink Device"
#endif

#endif /* __PROJECT_FLIGHT_CONFIG_H */
"""


def _ResourceHeader_Render(model: ProjectModel, catalog: PluginCatalog) -> str:
    catalog = catalog.ProjectView_Get(model)
    result = ResourceAssignments_Resolve(model, catalog)
    if not result.valid:
        raise ValueError("Cannot generate resource header: " + "; ".join(result.errors))
    includes = set()
    values: dict[str, str] = {}
    assigned_macros: set[str] = set()
    instance_plugins = {
        instance.instance_id: catalog.InstanceComponent_Get(instance)
        for instance in model.device_instances
    }
    for assignment in result.assignments:
        owner_manifest = instance_plugins.get(assignment.component_id)
        if (
            owner_manifest is not None
            and owner_manifest.instance_resource_binding is not None
        ):
            continue
        macro = assignment.requirement.binding_macro
        if not macro:
            continue
        header = assignment.provision.metadata.get("header")
        if isinstance(header, str) and header:
            includes.add(header)
        c_id = assignment.provision.metadata.get("c_id", assignment.provision.resource_id)
        if macro in values and values[macro] != c_id:
            raise ValueError(f"Resource binding macro is ambiguous: {macro}")
        values[macro] = str(c_id)
        assigned_macros.add(macro)
    optional_bindings_by_macro: dict[str, object] = {}
    for manifest in catalog.All_Get():
        raw_bindings = manifest.metadata.get("optional_resource_bindings", [])
        if not isinstance(raw_bindings, list):
            raise ValueError(
                f"Component {manifest.component_id} optional_resource_bindings "
                "must be an array"
            )
        for binding in raw_bindings:
            if not isinstance(binding, dict):
                raise ValueError("Component optional resource binding is invalid")
            macro = binding.get("binding_macro")
            if not isinstance(macro, str):
                raise ValueError("Component optional resource binding is invalid")
            previous = optional_bindings_by_macro.setdefault(macro, binding)
            if previous != binding:
                raise ValueError(
                    f"Optional resource binding is ambiguous: {macro}"
                )
    optional_bindings = tuple(optional_bindings_by_macro.values())
    identifier_pattern = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
    macro_pattern = re.compile(r"[A-Z][A-Z0-9_]*")
    for binding in optional_bindings:
        if not isinstance(binding, dict) or set(binding) != {
            "binding_macro",
            "enabled_macro",
            "fallback",
            "header",
        }:
            raise ValueError("Component optional resource binding is invalid")
        macro = binding.get("binding_macro")
        enabled_macro = binding.get("enabled_macro")
        fallback = binding.get("fallback")
        header = binding.get("header")
        if (
            not isinstance(macro, str)
            or macro_pattern.fullmatch(macro) is None
            or not isinstance(enabled_macro, str)
            or macro_pattern.fullmatch(enabled_macro) is None
            or not isinstance(fallback, str)
            or identifier_pattern.fullmatch(fallback) is None
            or not isinstance(header, str)
            or re.fullmatch(r"[A-Za-z0-9_./-]+\.h", header) is None
            or ".." in Path(header).parts
        ):
            raise ValueError("Component optional resource binding token is unsafe")
        includes.add(header)
        values.setdefault(macro, fallback)
        values[enabled_macro] = "1U" if macro in assigned_macros else "0U"
    include_text = "\n".join(f'#include "{header}"' for header in sorted(includes))
    define_text = "\n".join(
        f"#define {macro:<42} {value}" for macro, value in values.items()
    )
    instance_declarations = _InstanceResourceDeclarations_Render(model, catalog)
    return f"""#ifndef __PROJECT_RESOURCES_H
#define __PROJECT_RESOURCES_H

{AUTOGEN_C_COMMENT}

{include_text}

#include "{catalog.Component_Get(model.mcu).platform.resource_header}"
#include "system_device_types.h"

{define_text}

{instance_declarations}

{_PlatformUartConfigDefines_Render(model, catalog)}
#endif /* __PROJECT_RESOURCES_H */
"""


def _InstanceBindingGroups_Get(model: ProjectModel, catalog: PluginCatalog):
    catalog = catalog.ProjectView_Get(model)
    groups: dict[str, tuple[PluginManifest, list[DeviceInstance]]] = {}
    for instance in model.device_instances:
        manifest = catalog.InstanceComponent_Get(instance)
        binding = manifest.instance_resource_binding
        if binding is None:
            continue
        if binding.accessor not in groups:
            groups[binding.accessor] = (manifest, [])
        elif len(binding.fields) > len(groups[binding.accessor][0].instance_resource_binding.fields):
            groups[binding.accessor] = (manifest, groups[binding.accessor][1])
        groups[binding.accessor][1].append(instance)
    return tuple(groups[key] for key in sorted(groups))


def _InstanceResourceDeclarations_Render(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    sections: list[str] = []
    for manifest, instances in _InstanceBindingGroups_Get(model, catalog):
        binding = manifest.instance_resource_binding
        assert binding is not None
        requirement_by_name = {
            requirement.name: requirement
            for requirement in manifest.resource_requirements
        }
        fields = []
        for field in binding.fields:
            requirement = requirement_by_name[field.requirement]
            platform_kind = (
                "gpio" if requirement.kind.startswith("gpio_") else requirement.kind
            )
            platform_binding = catalog.Component_Get(
                model.mcu
            ).platform.resource_bindings.get(platform_kind)
            if platform_binding is None:
                raise ValueError(
                    f"Platform has no typed resource binding for {requirement.kind}"
                )
            fields.append(f"    {platform_binding.id_type} {field.member};")
        if binding.accessor == "ProjectSx1281Resources_Get" and not any(field.member == "rx_en" for field in binding.fields):
            fields.extend(("    PlatformGpioId rx_en;", "    PlatformGpioId tx_en;"))
        if binding.accessor == "ProjectJy901bResources_Get":
            fields.append("    uint16_t installation_orientation;")
            fields.append("    uint8_t module_variant;")
        if manifest.component_id in RAW_IMU_MOUNT_PLUGINS:
            fields.append("    int8_t axis_map[3];")
        sections.append(
            f"#define {binding.count_symbol:<42} {len(instances)}U\n"
            f"#define {binding.count_symbol}_MAX{' ' * max(1, 38 - len(binding.count_symbol))} "
            f"{max(1, len(instances)) if model.build.compact_mode else binding.runtime_context_upper_bound}U\n\n"
            f"typedef struct\n{{\n" + "\n".join(fields) + "\n"
            f"}} {binding.struct_type};\n\n"
            f"SystemDeviceResult {binding.accessor}(\n"
            f"    uint8_t source_instance, {binding.struct_type} *resources);"
        )
    return "\n\n".join(sections)


def _InstanceResourcesSource_Render(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    catalog = catalog.ProjectView_Get(model)
    resolution = ResourceAssignments_Resolve(model, catalog)
    if not resolution.valid:
        raise ValueError(
            "Cannot generate instance resource tables: "
            + "; ".join(resolution.errors)
        )
    assignments = {
        (assignment.component_id, assignment.requirement.name): assignment
        for assignment in resolution.assignments
    }
    sections: list[str] = []
    resource_value = re.compile(
        r"(?:[A-Za-z_][A-Za-z0-9_]*|"
        r"\(\([A-Za-z_][A-Za-z0-9_]*\)[0-9]+U\))"
    )
    for manifest, instances in _InstanceBindingGroups_Get(model, catalog):
        binding = manifest.instance_resource_binding
        assert binding is not None
        rows: list[str] = []
        for instance in instances:
            values: list[str] = []
            for field in binding.fields:
                assignment = assignments.get((instance.instance_id, field.requirement))
                if assignment is None:
                    if (binding.accessor == "ProjectSx1281Resources_Get" and
                            field.member in {"rx_en", "tx_en"}):
                        from silverstar_fccg.project.radio_variants import EBYTE_VARIANTS, LEGACY_MODULE
                        capability = EBYTE_VARIANTS[instance.module_variant or LEGACY_MODULE]
                        if not capability.external_frontend:
                            values.append(f".{field.member} = (PlatformGpioId)PLATFORM_GPIO_COUNT")
                            continue
                    raise ValueError(
                        f"Missing instance resource assignment: "
                        f"{instance.instance_id}:{field.requirement}"
                    )
                c_id = str(
                    assignment.provision.metadata.get(
                        "c_id", assignment.provision.resource_id
                    )
                )
                if resource_value.fullmatch(c_id) is None:
                    raise ValueError(
                        f"Instance resource C identifier is unsafe: {c_id}"
                    )
                values.append(f".{field.member} = {c_id}")
            if binding.accessor == "ProjectSx1281Resources_Get" and not any(field.member == "rx_en" for field in binding.fields):
                values.extend((".rx_en = (PlatformGpioId)PLATFORM_GPIO_COUNT", ".tx_en = (PlatformGpioId)PLATFORM_GPIO_COUNT"))
            if binding.accessor == "ProjectJy901bResources_Get":
                orientation = {"horizontal": 0, "vertical": 1}[instance.installation_orientation]
                variant = {"": 0, "jy901b": 0, "jy901s": 1}[instance.profile]
                values.append(f".installation_orientation = {orientation}U")
                values.append(f".module_variant = {variant}U")
            if manifest.component_id in RAW_IMU_MOUNT_PLUGINS:
                axes = RAW_IMU_NOSE_AXIS_MAPS[instance.mount_nose_axis]
                values.append(".axis_map = { " + ", ".join(map(str, axes)) + " }")
            rows.append("    { " + ", ".join(values) + " }")
        table_symbol = f"s_{binding.accessor.removesuffix('_Get')}"
        sections.append(
            f"_Static_assert({binding.count_symbol} <= {binding.count_symbol}_MAX,\n"
            f"    \"{manifest.component_id} instance count exceeds context bound\");\n\n"
            f"static const {binding.struct_type} {table_symbol}[{binding.count_symbol}] =\n"
            "{\n" + ",\n".join(rows) + "\n};\n\n"
            f"SystemDeviceResult {binding.accessor}(\n"
            f"    uint8_t source_instance, {binding.struct_type} *resources)\n"
            "{\n"
            "    if (resources == NULL) { return SYSTEM_DEVICE_INVALID_ARGUMENT; }\n"
            f"    if (source_instance >= {binding.count_symbol})\n"
            "    {\n"
            "        return SYSTEM_DEVICE_NOT_PRESENT;\n"
            "    }\n"
            f"    *resources = {table_symbol}[source_instance];\n"
            "    return SYSTEM_DEVICE_OK;\n"
            "}"
        )
    body = "\n\n".join(sections)
    return f"""#include "project_resources.h"

{AUTOGEN_C_COMMENT}

#include <stddef.h>

{body}
"""


def _StorageBindingHeader_Render(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    binding = StorageBinding_Resolve(model, catalog)
    if not binding.valid:
        raise ValueError("\n".join(f"{issue.code}: {issue.message}" for issue in binding.issues))
    object_symbol, path_symbol, driver_symbol = (
        binding.object_symbol, binding.path_symbol, binding.driver_symbol,
    )
    return f"""#ifndef __PROJECT_STORAGE_BINDING_H
#define __PROJECT_STORAGE_BINDING_H

{AUTOGEN_C_COMMENT}

#include "fatfs.h"

#define PROJECT_STORAGE_FATFS_OBJECT {object_symbol}
#define PROJECT_STORAGE_FATFS_PATH   {path_symbol}
#define PROJECT_STORAGE_FATFS_DRIVER {driver_symbol}

{MissionRadioProfileMacros_Render(model)}
#endif /* __PROJECT_STORAGE_BINDING_H */
"""


def _PlatformUartConfigDefines_Render(model: ProjectModel, catalog: PluginCatalog) -> str:
    """Size bounded F4 queues from the same logical bindings as the HAL table."""
    resolution = ResourceAssignments_Resolve(model, catalog, auto_assign=False)
    active_ids = {a.provision.resource_id for a in resolution.assignments}
    collections = (
        _CustomPlatformResources_Get(model, active_ids)
        if model.hardware.mode == "custom"
        else _BoardPlatformResources_Get(catalog.Component_Get(model.board), active_ids)
    )
    console_owners = {i.instance_id for i in model.device_instances
                      if i.plugin == "silverstar.device.console.uart"}
    console_ids = {a.provision.resource_id for a in resolution.assignments
                   if a.provision.kind == "uart" and a.component_id in console_owners}
    slots: dict[int, bool] = {}
    for fallback, entry in enumerate(collections.get("uarts", [])):
        index = _PlatformLogicalIndex_Get(entry, fallback)
        if "logical_index" not in entry and "fixed_logical_index" not in entry:
            token = str(entry.get("c_id", ""))
            match = re.fullmatch(r"PLATFORM_UART_([1-6])", token)
            cast = re.fullmatch(r"\(\(PlatformUartId\)([0-5])U\)", token)
            if match:
                index = int(match.group(1)) - 1
            elif cast:
                index = int(cast.group(1))
        if not isinstance(index, int) or isinstance(index, bool) or not 0 <= index < 6:
            raise ValueError("F4 UART buffer binding exceeds six logical slots")
        slots[index] = entry.get("id") in console_ids or index == 2
    lines = ["/* Bounded UART buffers follow the generated HAL logical-slot table. */"]
    for index in range(6):
        enabled = index in slots
        # One-byte inactive sentinels keep ISO C arrays valid without reserving queues.
        sizes = (128, 512 if index == 0 else 1024, 2048 if slots.get(index) else 192, 1024 if slots.get(index) else 192) if enabled else (1, 1, 1, 1)
        for kind, size in zip(("RX_DMA", "RX_RING", "TX_RING", "TX_PRIORITY"), sizes):
            lines.append(f"#define PROJECT_PLATFORM_UART_{index + 1}_{kind}_SIZE {size}U")
    return "\n".join(lines) + "\n"


def _PlatformResources_Render(model: ProjectModel, catalog: PluginCatalog) -> str:
    manifest = catalog.Component_Get(model.mcu)
    contract = manifest.platform
    if contract is None:
        raise ValueError(
            f"Selected MCU has no Platform resource contract: {model.mcu}"
        )
    resolution = ResourceAssignments_Resolve(model, catalog, auto_assign=False)
    active_resource_ids = {
        assignment.provision.resource_id for assignment in resolution.assignments
    }
    if model.hardware.mode == "custom":
        collections = _CustomPlatformResources_Get(model, active_resource_ids)
    else:
        board = catalog.Component_Get(model.board)
        collections = _BoardPlatformResources_Get(
            board, active_resource_ids
        )
        _BoardPlatformResourceClosure_Validate(
            board, resolution.assignments, collections, contract.resource_bindings
        )
    raw_capacities = manifest.metadata.get("resource_capacities", {})
    if not isinstance(raw_capacities, dict):
        raise ValueError("Platform resource_capacities must be an object")
    for collection, entries in collections.items():
        capacity = raw_capacities.get(collection)
        if capacity is None:
            continue
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
            raise ValueError(
                f"Platform resource capacity is invalid: {collection}"
            )
        for fallback_index, entry in enumerate(entries):
            logical_index = _PlatformLogicalIndex_Get(entry, fallback_index)
            if (
                not isinstance(logical_index, int)
                or isinstance(logical_index, bool)
                or logical_index < 0
                or logical_index >= capacity
            ):
                raise ValueError(
                    f"Platform resource {collection} exceeds capacity {capacity}"
                )
    includes: set[str] = set()
    sections: list[str] = []
    for kind, binding in contract.resource_bindings.items():
        entries = collections.get(binding.collection, [])
        if not entries:
            continue
        includes.add(binding.include_header)
        sections.append(_PlatformBinding_Render(binding, entries))
    include_text = "\n".join(
        f'#include "{header}"' for header in sorted(includes)
    )
    body = "\n\n".join(sections)
    return f"""#include "{contract.resource_header}"

{AUTOGEN_C_COMMENT}

#include <stddef.h>

{include_text}

{body}
"""


def _CIdentifier_Require(value: Any, field_name: str) -> str:
    if not isinstance(value, str) or re.fullmatch(
        r"[A-Za-z_][A-Za-z0-9_]*", value
    ) is None:
        raise ValueError(f"Platform resource {field_name} is not a safe C identifier")
    return value


def _PlatformLogicalIndex_Get(entry: dict[str, Any], fallback_index: int) -> Any:
    if entry.get("binding_origin") == VERIFIED_BOARD_BINDING_ORIGIN:
        return entry.get("fixed_logical_index")
    return entry.get("logical_index", fallback_index)


def _PlatformEntryResolvedSymbol_Get(entry: dict[str, Any]) -> str:
    port = entry.get("port")
    pin = entry.get("pin")
    if isinstance(port, str) and port and isinstance(pin, str) and pin:
        return f"{port}/{pin}"
    handle = entry.get("handle")
    channel = entry.get("channel_token")
    if isinstance(handle, str) and handle:
        return (
            f"{handle}/{channel}"
            if isinstance(channel, str) and channel
            else handle
        )
    return str(entry.get("physical_alias", "<unresolved>"))


def _BoardPlatformResourceClosure_Validate(
    board: PluginManifest,
    assignments: tuple[Any, ...],
    collections: dict[str, list[dict[str, Any]]],
    bindings: dict[str, Any],
) -> None:
    if board.board is None or not board.board.verified:
        return
    entries_by_id: dict[str, dict[str, Any]] = {}
    for entries in collections.values():
        for entry in entries:
            resource_id = entry.get("id")
            if not isinstance(resource_id, str) or not resource_id:
                continue
            if resource_id in entries_by_id:
                raise ValueError(
                    "Platform Resource Closure Check failed: "
                    f"duplicate logical ID {resource_id}, Board plugin "
                    f"{board.component_id}"
                )
            entries_by_id[resource_id] = entry
    binding_kinds = set(bindings)
    for assignment in assignments:
        provision = assignment.provision
        metadata = provision.metadata
        if metadata.get("binding_origin") != VERIFIED_BOARD_BINDING_ORIGIN:
            continue
        platform_kind = (
            "gpio" if provision.kind.startswith("gpio_") else provision.kind
        )
        if platform_kind not in binding_kinds:
            continue
        logical_id = provision.resource_id
        expected_alias = str(metadata.get("physical_alias", ""))
        entry = entries_by_id.get(logical_id)
        actual_symbol = (
            _PlatformEntryResolvedSymbol_Get(entry)
            if entry is not None
            else "<missing table entry>"
        )
        expected_symbol = _PlatformEntryResolvedSymbol_Get(metadata)
        if (
            entry is None
            or entry.get("c_id") != logical_id
            or entry.get("physical_alias") != expected_alias
            or actual_symbol != expected_symbol
        ):
            raise ValueError(
                "Platform Resource Closure Check failed: "
                f"logical ID {logical_id}, expected alias {expected_alias}, "
                f"actual symbol {actual_symbol}, Board plugin "
                f"{board.component_id}"
            )


def _PlatformBinding_Render(binding, entries: list[dict[str, Any]]) -> str:
    values: list[str] = []
    valid_values: list[str] = []
    declarations: list[str] = []
    for entry in entries:
        logical_index = entry.get("logical_index")
        if entry.get("binding_origin") == VERIFIED_BOARD_BINDING_ORIGIN:
            designator = _CIdentifier_Require(entry.get("c_id"), "c_id")
        elif isinstance(logical_index, int) and 0 <= logical_index <= 0xFFFF:
            designator = f"{logical_index}U"
        else:
            designator = _CIdentifier_Require(entry.get("c_id"), "c_id")
        if binding.entry_kind == "handle":
            handle = _CIdentifier_Require(entry.get("handle"), "handle")
            initializer = f"&{handle}"
        elif binding.entry_kind == "gpio":
            port = _CIdentifier_Require(entry.get("port"), "GPIO port")
            pin = _CIdentifier_Require(entry.get("pin"), "GPIO pin")
            irq_enabled = int(
                bool(entry.get("irq_enabled", entry.get("active_high", 0)))
            )
            initializer = f"{{{port}, {pin}, {irq_enabled}U}}"
        elif binding.entry_kind == "pwm":
            handle = _CIdentifier_Require(entry.get("handle"), "PWM handle")
            channel = _CIdentifier_Require(
                entry.get("channel_token"), "PWM channel"
            )
            pwm_mode = {
                "pwm1": "PLATFORM_PWM_MODE_1",
                "pwm2": "PLATFORM_PWM_MODE_2",
            }.get(str(entry.get("pwm_mode", "")).casefold())
            if pwm_mode is None:
                raise ValueError(
                    "PWM resource has no supported CubeMX PWM1/PWM2 mode"
                )
            numeric_fields = (
                int(entry.get("frequency_hz", 0)),
                int(entry.get("resolution_bits", 0)),
                int(bool(entry.get("active_high", 1))),
            )
            if any(value < 0 or value > 0xFFFFFFFF for value in numeric_fields):
                raise ValueError("PWM resource metadata is out of range")
            initializer = (
                f"{{&{handle}, {channel}, {numeric_fields[0]}U, "
                f"{numeric_fields[1]}U, {pwm_mode}, "
                f"{numeric_fields[2]}U}}"
            )
        elif binding.entry_kind == "timebase":
            handle = _CIdentifier_Require(entry.get("handle"), "Timebase handle")
            handle_type = _CIdentifier_Require(
                entry.get("handle_type"), "Timebase handle type"
            )
            declaration = f"extern {handle_type} {handle};"
            if declaration not in declarations:
                declarations.append(declaration)
            numeric_fields = (
                int(entry.get("counter_frequency_hz", 0)),
                int(entry.get("period_counts", 0)),
                int(entry.get("tick_frequency_hz", 0)),
            )
            if any(value <= 0 or value > 0xFFFFFFFF for value in numeric_fields):
                raise ValueError("Timebase resource metadata is out of range")
            initializer = (
                f"{{&{handle}, {numeric_fields[0]}U, {numeric_fields[1]}U, "
                f"{numeric_fields[2]}U}}"
            )
        elif binding.entry_kind == "systick":
            frequency = int(entry.get("tick_frequency_hz", 0))
            if frequency != 1_000:
                raise ValueError("SysTick resource must have a verified 1 kHz HAL tick")
            initializer = f"{{{frequency}U}}"
        else:
            raise ValueError(
                f"Unsupported Platform resource entry kind: {binding.entry_kind}"
            )
        values.append(f"    [{designator}] = {initializer}")
        valid_values.append(f"    [{designator}] = 1U")
    initializer_text = ",\n".join(values)
    if binding.entry_kind == "handle":
        return f"""static void * const {binding.table_symbol}[{binding.count_symbol}] =
{{
{initializer_text}
}};

void *{binding.getter}({binding.id_type} id)
{{
    return ((uint32_t)id < (uint32_t){binding.count_symbol}) ?
        {binding.table_symbol}[id] : NULL;
}}"""
    declaration_text = "\n".join(declarations)
    declaration_block = f"{declaration_text}\n\n" if declaration_text else ""
    validity_text = ",\n".join(valid_values)
    validity_symbol = f"{binding.table_symbol}_valid"
    return f"""{declaration_block}static const {binding.struct_type}
    {binding.table_symbol}[{binding.count_symbol}] =
{{
{initializer_text}
}};

static const uint8_t {validity_symbol}[{binding.count_symbol}] =
{{
{validity_text}
}};

uint8_t {binding.getter}(
    {binding.id_type} id,
    {binding.struct_type} *resource)
{{
    if (((uint32_t)id >= (uint32_t){binding.count_symbol}) ||
        ({validity_symbol}[id] == 0U) ||
        (resource == NULL))
    {{
        return 0U;
    }}
    *resource = {binding.table_symbol}[id];
    return 1U;
}}"""


def _CustomPlatformResources_Get(
    model: ProjectModel, active_resource_ids: set[str]
) -> dict[str, list[dict[str, Any]]]:
    platform: dict[str, list[dict[str, Any]]] = {
        "uarts": [],
        "spis": [],
        "adcs": [],
        "gpios": [],
        "i2cs": [],
        "cans": [],
        "pwms": [],
        "timebases": [],
    }
    destinations = {
        "uart": "uarts",
        "spi": "spis",
        "adc": "adcs",
        "i2c": "i2cs",
        "can_classic": "cans",
        "pwm": "pwms",
        "time": "timebases",
    }
    for resource in model.hardware.resources:
        metadata = resource.metadata
        destination = destinations.get(resource.kind)
        if (
            resource.kind in {"i2c", "can_classic", "pwm", "time"}
            and resource.resource_id not in active_resource_ids
        ):
            continue
        if destination is not None and isinstance(metadata.get("handle"), str):
            entry = {"id": resource.resource_id, **metadata}
            entry.pop("binding_origin", None)
            entry.pop("fixed_logical_index", None)
            platform[destination].append(entry)
        elif resource.kind.startswith("gpio_") and isinstance(metadata.get("port"), str):
            entry = {"id": resource.resource_id, **metadata}
            entry.pop("binding_origin", None)
            entry.pop("fixed_logical_index", None)
            platform["gpios"].append(entry)
    for values in platform.values():
        values.sort(key=lambda entry: int(entry.get("logical_index", 0)))
    return platform


def _BoardPlatformResources_Get(
    board, active_resource_ids: set[str]
) -> dict[str, list[dict[str, Any]]]:
    if board.board is not None and not board.board.ioc_file:
        legacy = board.metadata.get("platform_resources")
        if isinstance(legacy, dict):
            provisions = {
                provision.resource_id: provision
                for provision in board.resource_provisions
            }
            normalized: dict[str, list[dict[str, Any]]] = {}
            for collection, entries in legacy.items():
                if not isinstance(collection, str) or not isinstance(entries, list):
                    raise ValueError("Legacy Board platform_resources is invalid")
                normalized_entries: list[dict[str, Any]] = []
                for entry in entries:
                    if not isinstance(entry, dict):
                        raise ValueError("Legacy Board platform resource is invalid")
                    resource_id = entry.get("id")
                    if not isinstance(resource_id, str) or not resource_id:
                        raise ValueError("Legacy Board platform resource has no id")
                    normalized_entry = dict(entry)
                    provision = provisions.get(resource_id)
                    if provision is not None and "c_id" not in normalized_entry:
                        normalized_entry["c_id"] = provision.metadata.get("c_id")
                    normalized_entries.append(normalized_entry)
                normalized[collection] = normalized_entries
            return normalized
    platform: dict[str, list[dict[str, Any]]] = {
        "uarts": [],
        "spis": [],
        "adcs": [],
        "gpios": [],
        "i2cs": [],
        "cans": [],
        "pwms": [],
        "timebases": [],
    }
    destinations = {
        "uart": "uarts",
        "spi": "spis",
        "adc": "adcs",
        "i2c": "i2cs",
        "can_classic": "cans",
        "pwm": "pwms",
        "time": "timebases",
    }
    for provision in BoardResourceProvisions_Get(board):
        metadata = provision.metadata
        destination = destinations.get(provision.kind)
        if (
            provision.kind in {"i2c", "can_classic", "pwm", "time"}
            and provision.resource_id not in active_resource_ids
        ):
            continue
        if destination is not None and isinstance(metadata.get("handle"), str):
            platform[destination].append(
                {"id": provision.resource_id, **metadata}
            )
        elif provision.kind.startswith("gpio_") and isinstance(
            metadata.get("port"), str
        ):
            platform["gpios"].append(
                {"id": provision.resource_id, **metadata}
            )
    for values in platform.values():
        values.sort(
            key=lambda entry: (
                int(entry.get("fixed_logical_index", 0)),
                str(entry.get("c_id", "")),
            )
        )
    return platform


def _LogMetadataDeclarations_Get(model: ProjectModel, catalog: PluginCatalog,
    metadata: dict[str, Any]) -> dict[str, Any]:
    declarations = deepcopy(metadata.get("project_semantics", {}))
    owners: set[str] = set()
    for component_id in model.ComponentIds_Get():
        manifest = catalog.Component_Get(component_id)
        if manifest.component_type != "algorithm":
            continue
        fragments = manifest.metadata.get("navigation_semantics", {})
        if not isinstance(fragments, dict):
            raise ValueError(f"{component_id}: navigation_semantics must be an object")
        for name, declaration in fragments.items():
            if name in owners or not isinstance(declaration, dict):
                raise ValueError(f"{component_id}: duplicate or invalid navigation semantics {name}")
            owners.add(name)
            declarations[name] = deepcopy(declaration)
            if name == "kf6":
                from silverstar_fccg.generator.kf6_identity import KERNEL_PATHS
                provenance = (model.component_provenance.get(component_id)
                              or ComponentProvenance_Get(catalog, component_id))
                files = provenance.get("files", {})
                if not all(path in files for path in KERNEL_PATHS):
                    raise ValueError("KF6 source model identity NOT PROVEN: missing kernel provenance")
                upstream_files = ComponentProvenance_Get(catalog, component_id)["files"]
                if any(files[path] != upstream_files[path] for path in KERNEL_PATHS):
                    raise ValueError("KF6 source model identity NOT PROVEN: catalog declaration differs from kernel provenance")
                declarations[name]["kernel_sha256"] = {
                    path: files[path] for path in KERNEL_PATHS}
    return declarations


def LogDecoderProfile_Render(
    model: ProjectModel, catalog: PluginCatalog
) -> LogDecoderPackageResult:
    logging_selection = model.protocols.get("logging")
    if logging_selection is None:
        raise ValueError("Decoder generation requires one Logging Protocol")
    protocol = catalog.Component_Get(logging_selection.component)
    metadata_path = ProjectProtocolLogMetadataPath_Get(model, catalog)
    metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    schema_relative = metadata.get("reference_schema")
    if not isinstance(schema_relative, str) or not schema_relative:
        raise ValueError("Protocol decoder metadata has no reference schema")
    schema_path = protocol.payload_root.joinpath(*schema_relative.split("/")).resolve()
    try:
        schema_path.relative_to(protocol.payload_root.resolve())
    except ValueError as error:
        raise ValueError("Protocol record schema leaves its payload") from error
    if schema_path.is_symlink() or not schema_path.is_file():
        raise ValueError("Protocol record schema is missing or unsafe")
    schema = json.loads(schema_path.read_text(encoding="utf-8"))
    definitions = ProtocolLogDefinitions_Get(model, catalog)
    capability_resolution = CapabilityResolution_Resolve(model, catalog)
    resource_resolution = ResourceAssignments_Resolve(model, catalog)
    if not resource_resolution.valid:
        raise ValueError(
            "Cannot generate decoder semantics with unresolved hardware resources"
        )
    descriptor_entries = _DeviceDescriptorEntries_Get(model, catalog)
    physical_device_ids = dict(
        _PhysicalDeviceDefinitions_Get(catalog, descriptor_entries)
    )
    physical_devices = _LogPhysicalDevices_Get(
        model, catalog, descriptor_entries, physical_device_ids
    )
    capability_endpoints = _LogCapabilityEndpoints_Get(
        catalog, descriptor_entries, physical_device_ids
    )
    protocol_resolution = ProtocolResolution_Resolve(model, catalog)
    if not protocol_resolution.valid:
        raise ValueError("Cannot generate unresolved protocol transport bindings")
    project_semantics = {
        "schema_id": "silverstar.project-semantics/1.2",
        "project": model.identity.name,
        "target": model.build.target_profile,
        "firmware_version": model.identity.firmware_version,
        "project_digest": f"{ProjectDigest_Get(model):08x}",
        "protocols": _ProtocolSelectionsDictionary_Get(model),
        "components": list(model.ComponentIds_Get()),
        "component_locks": [
            {
                "component": component_id,
                "version": catalog.Component_Get(component_id).version,
                "manifest_sha256": catalog.Component_Get(
                    component_id
                ).ManifestSha256_Get(),
            }
            for component_id in model.ComponentIds_Get()
        ],
        "algorithms": [
            component_id
            for component_id in model.ComponentIds_Get()
            if catalog.Component_Get(component_id).component_type == "algorithm"
        ],
        "hardware": {
            "mode": model.hardware.mode,
            "source_kind": model.hardware.source_kind,
            "provider": model.hardware.provider,
            "board": model.board,
            "matched_mcu_platform": model.mcu,
            "platform_lock": {
                "component": model.hardware.platform_component,
                "version": model.hardware.platform_version,
                "manifest_sha256": model.hardware.platform_manifest_sha256,
            },
            "detected_mcu": model.hardware.mcu,
            "mcu_family": model.hardware.inventory.get("mcu_family", ""),
            "package": model.hardware.inventory.get("package", ""),
            "core": model.hardware.inventory.get("core", ""),
            "cubemx_version": model.hardware.cubemx_version,
            "firmware_package": model.hardware.firmware_package,
            "hal_cmsis_source_policy": model.hardware.hal_cmsis_source_policy,
            "snapshot_id": model.hardware.snapshot_id,
            "source_digest": model.hardware.source_digest,
            "assignment_fingerprint": model.hardware.assignment_fingerprint,
        },
        "resource_assignments": [
            {
                "requirement": assignment.requirement_key,
                "owner": assignment.component_id,
                "kind": assignment.requirement.kind,
                "logical_resource": assignment.provision.resource_id,
                "physical_resource": assignment.provision.metadata.get(
                    "physical_resource", assignment.provision.resource_id
                ),
                "peripheral": assignment.provision.metadata.get("peripheral", ""),
                "pins": assignment.provision.metadata.get("pins", {}),
            }
            for assignment in sorted(
                resource_resolution.assignments,
                key=lambda item: item.requirement_key,
            )
        ],
        "devices": physical_devices,
        "physical_devices": physical_devices,
        "physical_device_ids": {
            symbol: value
            for symbol, value in sorted(
                physical_device_ids.items(), key=lambda item: item[1]
            )
        },
        "device_descriptors": [
            {
                "descriptor_id": entry["_descriptor_id"],
                "descriptor_symbol": entry["_descriptor_symbol"],
                "physical_device_id": physical_device_ids[
                    entry["physical_device_id"]
                ],
                "physical_device_symbol": entry["physical_device_id"],
                "device_class": entry["class"],
                "instance_id": entry["_instance_id"],
                "source_instance_id": entry["_source_instance_id"],
                "source_component": entry["_component_id"],
            }
            for entry in descriptor_entries
        ],
        "capability_endpoints": capability_endpoints,
        "capability_routes": [
            {
                "capability": route.requirement.capability,
                "purpose": route.requirement.purpose,
                "consumer": route.requirement.consumer_component,
                "provider_instance": route.provider.instance_id,
                "provider_plugin": route.provider.plugin,
                "automatic": route.automatic,
            }
            for route in capability_resolution.routes
        ],
        "canonical_channels": _LogCanonicalChannels_Get(
            capability_resolution, capability_endpoints
        ),
        "enabled_capabilities": {
            instance_id: list(capabilities)
            for instance_id, capabilities in sorted(
                capability_resolution.enabled_by_instance.items()
            )
        },
        "strategies": dict(sorted(model.strategies.items())),
        "modes": {
            slot: list(values) for slot, values in sorted(model.modes.items())
        },
        "mode_parameters": model.mode_parameters,
        "firmware_algorithm_parameters": AlgorithmParameters_Resolve(model, catalog),
        "protocol_bindings": [
            {
                "service": binding.service,
                "slot": binding.slot,
                "profile_id": binding.profile_id,
                "binding": binding.binding,
                "transport_capability": binding.transport_capability,
                "transport_selection": binding.transport_selection,
                "physical_device_instance": binding.provider_instance,
                "physical_device_plugin": binding.provider_component,
                "candidate_instances": list(binding.candidate_instances),
            }
            for binding in protocol_resolution.bindings
        ],
        "available_records": [
            {
                "record": definition.record,
                "level": definition.level.value,
                "available": availability.available and FeatureTier_LogRecordAllowed(model, definition.record),
                "reason_code": (availability.reason_code if FeatureTier_LogRecordAllowed(model, definition.record)
                                else FeatureTier_LogRecordReasonGet(model, definition.record)),
                "missing": list(availability.missing),
                "producer_components": list(
                    definition.producer_components
                ),
                "active_producers": sorted(
                    set(definition.producer_components).intersection(
                        ProjectLogProducers_Get(model, catalog)
                    )
                ),
            }
            for definition in definitions
            for availability in (
                LogAvailability_Get(definition, model, catalog),
            )
        ],
        **({"logging_profile": model.build.logging_profile}
           if model.build.logging_profile != "all_streams" else {}),
        "logging_streams": [
            {
                "record": stream.record,
                "enabled": stream.enabled,
                "policy": stream.policy,
                "decimation_factor": stream.decimation,
                "period_us": stream.period_us,
            }
            for stream in CompactLogStreams_Get(model)
        ],
        "record_views": _LogRecordViews_Get(
            definitions, metadata, schema, model, catalog
        ),
        "raw_channel_id_templates": _LogRawChannelTemplates_Get(
            metadata, schema
        ),
        "event_catalog": _LogCatalogSection_Get(
            metadata, schema, "event_catalog"
        ),
        "enum_catalog": _LogCatalogSection_Get(
            metadata, schema, "enum_catalog"
        ),
        "metadata_declarations": _LogMetadataDeclarations_Get(model, catalog, metadata),
    }
    # The selected Logging Protocol owns the base catalog. Selected Device and
    # Algorithm plugins may append data-only fragments; conflicts are rejected
    # before any generated file is materialized.
    fragments: list[tuple[str, dict[str, Any]]] = []
    for component_id in model.ComponentIds_Get():
        manifest = catalog.Component_Get(component_id)
        if manifest.component_type not in {"device", "algorithm"}:
            continue
        fragment_paths = manifest.metadata.get("record_catalog_fragments", [])
        if not isinstance(fragment_paths, list):
            raise ValueError(
                f"{component_id}: metadata.record_catalog_fragments must be an array"
            )
        for fragment_path in fragment_paths:
            if not isinstance(fragment_path, str):
                raise ValueError(
                    f"{component_id}: Record Catalog fragment path must be text"
                )
            fragments.append(
                (
                    f"{component_id}:{fragment_path}",
                    RecordCatalogFragment_Load(manifest, fragment_path),
                )
            )
    record_catalog = RecordCatalog_Merge(schema, fragments)
    return LogDecoderPackage_Build(
        record_catalog,
        project_semantics,
        LogDecoderPackageContext(
            project_name=model.identity.name,
            firmware_version=model.identity.firmware_version,
            firmware_commit=str(model.reference_provenance.get("commit", "")),
            fccg_version=__version__,
            selected_log_format_profile=logging_selection.profile,
            container_plugin_id=_LogContainerId_Get(model, catalog),
            container_version=_LogContainerVersion_Get(model, catalog),
            creation_time_utc=str(
                model.reference_provenance.get(
                    "commit_time_utc",
                    model.reference_provenance.get("recorded_at_utc", ""),
                )
            ),
            project_generation_fingerprint=f"{ProjectDigest_Get(model):08x}",
            supported_primitive_types=_SupportedPrimitiveTypes_Get(schema),
            selected_protocols=_ProtocolSelectionsDictionary_Get(model),
            firmware_components={
                "core": model.core,
                "mcu_platform": model.mcu,
                "board": model.board,
            },
            hardware_identity={
                "detected_mcu": model.hardware.mcu,
                "inventory": {
                    key: model.hardware.inventory.get(key, "")
                    for key in ("mcu_part", "mcu_family", "package", "core")
                },
                "snapshot_id": model.hardware.snapshot_id,
                "source_digest": model.hardware.source_digest,
                "cubemx_version": model.hardware.cubemx_version,
                "firmware_package": model.hardware.firmware_package,
                "hal_cmsis_source_policy": model.hardware.hal_cmsis_source_policy,
                "assignment_fingerprint": model.hardware.assignment_fingerprint,
                "platform_lock": {
                    "component": model.hardware.platform_component,
                    "version": model.hardware.platform_version,
                    "manifest_sha256": model.hardware.platform_manifest_sha256,
                },
            },
        ),
    )


def _LogContainerVersion_Get(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    selection = model.protocols.get("logging")
    if selection is None:
        raise ValueError("Decoder generation requires a Logging Protocol")
    contribution = catalog.Component_Get(selection.component).protocol
    matches = [] if contribution is None else [
        profile
        for profile in contribution.profiles.get("logging", ())
        if profile.profile_id == selection.profile
    ]
    if len(matches) != 1:
        raise ValueError(
            "Decoder generation requires exactly one selected logging profile"
        )
    return matches[0].version


def _LogContainerId_Get(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    selection = model.protocols.get("logging")
    if selection is None:
        raise ValueError("Decoder generation requires a Logging Protocol")
    manifest = catalog.Component_Get(selection.component)
    container = manifest.metadata.get("container_decoder", {})
    if not isinstance(container, dict):
        raise ValueError("Logging Protocol container decoder metadata is invalid")
    container_id = container.get("id")
    if not isinstance(container_id, str) or not container_id:
        raise ValueError("Logging Protocol container decoder id is missing")
    return container_id


def _SupportedPrimitiveTypes_Get(
    schema: dict[str, Any],
) -> tuple[str, ...]:
    records = schema.get("records", ())
    if not isinstance(records, list):
        raise ValueError("Protocol record schema records must be an array")
    primitive_types = {
        field["type"]
        for record in records
        if isinstance(record, dict)
        for fields in (record.get("fields", ()),)
        if isinstance(fields, list)
        for field in fields
        if isinstance(field, dict) and isinstance(field.get("type"), str)
    }
    if not primitive_types:
        raise ValueError("Protocol record schema declares no primitive types")
    return tuple(sorted(primitive_types))


def _LogPhysicalDevices_Get(
    model: ProjectModel,
    catalog: PluginCatalog,
    descriptor_entries: list[dict[str, Any]],
    physical_device_ids: dict[str, int],
) -> list[dict[str, Any]]:
    devices: list[dict[str, Any]] = []
    for instance in model.device_instances:
        manifest = catalog.InstanceComponent_Get(instance)
        physical = manifest.physical_device
        if physical is None:
            raise ValueError(
                f"Device plugin {instance.plugin} has no physical-device identity"
            )
        descriptors = [
            entry
            for entry in descriptor_entries
            if entry["_component_id"] == instance.plugin
            and entry["_source_instance_id"] == instance.instance_id
        ]
        physical_ids = sorted(
            {
                physical_device_ids[str(entry["physical_device_id"])]
                for entry in descriptors
            }
        )
        recordable_outputs = manifest.metadata.get("recordable_outputs", {})
        if not isinstance(recordable_outputs, dict):
            raise ValueError(
                f"Device plugin {instance.plugin} has invalid recordable outputs"
            )
        devices.append(
            {
                "instance_id": instance.instance_id,
                "physical_device_id": (
                    physical_ids[0] if len(physical_ids) == 1 else None
                ),
                "physical_device_ids": physical_ids,
                "descriptor_ids": [
                    int(entry["_descriptor_id"]) for entry in descriptors
                ],
                "plugin": instance.plugin,
                "component_class": manifest.component_class,
                "vendor": physical.vendor,
                "model": physical.model,
                "chipset": physical.chipset,
                "driver": physical.driver,
                **({"installation_orientation": instance.installation_orientation,
                    "orientation_config_source": "JY901B_ORIENT_0x23_module_internal"}
                   if instance.plugin == "silverstar.device.imu.jy901b" else {}),
                "capabilities": list(manifest.provides),
                "recordable_outputs": dict(
                    sorted(recordable_outputs.items())
                ),
            }
        )
    return devices


def _LogCapabilityEndpoints_Get(
    catalog: PluginCatalog,
    descriptor_entries: list[dict[str, Any]],
    physical_device_ids: dict[str, int],
) -> list[dict[str, Any]]:
    endpoints: list[dict[str, Any]] = []
    for entry in descriptor_entries:
        manifest = catalog.Component_Get(str(entry["_component_id"]))
        physical = manifest.physical_device
        endpoint_capabilities = entry.get("capabilities", manifest.provides)
        if not isinstance(endpoint_capabilities, (list, tuple)) or not all(
            isinstance(value, str) for value in endpoint_capabilities
        ):
            raise ValueError(
                f"Component {manifest.component_id} has invalid endpoint capabilities"
            )
        endpoints.append(
            {
                "descriptor_id": int(entry["_descriptor_id"]),
                "descriptor_symbol": str(entry["_descriptor_symbol"]),
                "physical_device_id": physical_device_ids[
                    str(entry["physical_device_id"])
                ],
                "physical_device_instance": str(entry["_source_instance_id"]),
                "device_class": str(entry["class"]),
                "instance_id": int(entry["_instance_id"]),
                "plugin": manifest.component_id,
                "model": physical.model if physical is not None else manifest.name,
                "capabilities": list(endpoint_capabilities),
            }
        )
    return endpoints


def _CapabilityDeviceClass_Get(capability: str) -> str:
    tokens = capability.split(".")
    root = tokens[1] if tokens[0] == "device" and len(tokens) > 1 else tokens[0]
    classes = {
        "attitude": "SYSTEM_DEVICE_CLASS_HARDWARE_QUATERNION",
        "barometer": "SYSTEM_DEVICE_CLASS_BAROMETER",
        "gnss": "SYSTEM_DEVICE_CLASS_GNSS",
        "imu": "SYSTEM_DEVICE_CLASS_IMU",
        "magnetometer": "SYSTEM_DEVICE_CLASS_MAGNETOMETER",
        "power": "SYSTEM_DEVICE_CLASS_POWER",
        "telemetry": "SYSTEM_DEVICE_CLASS_TELEMETRY",
    }
    return classes.get(root, "")


def _LogCanonicalChannels_Get(
    resolution: CapabilityResolution,
    capability_endpoints: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    channels: list[dict[str, Any]] = []
    for capability in sorted(
        {route.requirement.capability for route in resolution.routes}
    ):
        routes = [
            route
            for route in resolution.routes
            if route.requirement.capability == capability
        ]
        providers = {
            (route.provider.instance_id, route.provider.plugin)
            for route in routes
        }
        if len(providers) != 1:
            raise ValueError(
                f"Canonical capability {capability} has inconsistent routes"
            )
        provider_instance, provider_plugin = next(iter(providers))
        expected_class = _CapabilityDeviceClass_Get(capability)
        endpoint_ids = [
            int(endpoint["descriptor_id"])
            for endpoint in capability_endpoints
            if endpoint["physical_device_instance"] == provider_instance
            and endpoint["plugin"] == provider_plugin
            and (
                not expected_class
                or endpoint["device_class"] == expected_class
            )
        ]
        channels.append(
            {
                "channel_id": f"canonical:{capability}",
                "capability": capability,
                "physical_device_instance": provider_instance,
                "provider_plugin": provider_plugin,
                "endpoint_descriptor_ids": endpoint_ids,
                "automatic": all(route.automatic for route in routes),
            }
        )
    return channels


def _LogRecordViews_Get(
    definitions: tuple[LogRecordDefinition, ...],
    metadata: dict[str, Any],
    schema: dict[str, Any],
    model: ProjectModel,
    catalog: PluginCatalog,
) -> list[dict[str, Any]]:
    schema_records = {
        entry.get("enum"): entry
        for entry in schema.get("records", ())
        if isinstance(entry, dict) and isinstance(entry.get("enum"), str)
    }
    metadata_records = metadata.get("fccg", {}).get("records", {})
    if not isinstance(metadata_records, dict):
        metadata_records = {}
    streams = {stream.record: stream for stream in CompactLogStreams_Get(model)}
    active_producers = ProjectLogProducers_Get(model, catalog)
    views: list[dict[str, Any]] = []
    for definition in definitions:
        record = schema_records.get(definition.record, {})
        policy = metadata_records.get(definition.record, {})
        if not isinstance(policy, dict):
            policy = {}
        fields = record.get("fields", ())
        if not isinstance(fields, list):
            fields = []
        named_fields = [
            field for field in fields
            if isinstance(field, dict) and isinstance(field.get("name"), str)
        ]
        partition_by = record.get(
            "partition_by", policy.get("partition_by", [])
        )
        if not isinstance(partition_by, list):
            partition_by = []
        if not partition_by:
            field_names = {field["name"] for field in named_fields}
            partition_by = [
                name
                for name in (
                    "source_descriptor_id",
                    "instance_id",
                    "physical_device_id",
                )
                if name in field_names
            ]
        columns = record.get("columns", policy.get("columns"))
        if not isinstance(columns, list):
            columns = [field["name"] for field in named_fields]
        stream = streams.get(definition.record, definition.default_stream)
        availability = LogAvailability_Get(definition, model, catalog)
        enums = record.get("enums", policy.get("enums", {}))
        if not enums:
            enums = {
                field["name"]: {
                    key: field[key]
                    for key in ("enum", "bitfield")
                    if key in field
                }
                for field in named_fields
                if "enum" in field or "bitfield" in field
            }
        views.append(
            {
                "record": definition.record,
                "record_type": definition.record_id,
                "record_version": definition.version,
                "payload_size": definition.payload_size,
                "display_names": dict(sorted(definition.display_names.items())),
                "partition_by": partition_by,
                "columns": columns,
                "validity": record.get(
                    "validity", policy.get("validity", {})
                ),
                "events": record.get("events", policy.get("events", {})),
                "enums": enums,
                "cadence": {
                    "kind": definition.cadence.kind.value,
                    "source": definition.cadence.source,
                    "display_names": dict(
                        sorted(definition.cadence.display_names.items())
                    ),
                },
                "logging": {
                    "enabled": stream.enabled,
                    "policy": stream.policy,
                    "decimation_factor": stream.decimation,
                    "period_us": stream.period_us,
                },
                "producer_components": list(definition.producer_components),
                "active_producers": sorted(
                    set(definition.producer_components).intersection(
                        active_producers
                    )
                ),
                "available": availability.available and FeatureTier_LogRecordAllowed(model, definition.record),
            }
        )
    return views


def _LogRawChannelTemplates_Get(
    metadata: dict[str, Any], schema: dict[str, Any]
) -> dict[str, Any]:
    declared = metadata.get(
        "raw_channel_id_templates",
        schema.get("raw_channel_id_templates", {}),
    )
    if isinstance(declared, dict) and declared:
        return declared
    identity = metadata.get(
        "capability_source_identity",
        schema.get("capability_source_identity", {}),
    )
    if not isinstance(identity, dict):
        return {}
    partition_fields = [
        name
        for name in (
            "source_descriptor_id",
            "instance_id",
            "physical_device_id",
        )
        if name in identity
    ]
    if not partition_fields:
        return {}
    return {
        "default": "{record}:{source_descriptor_id}:{instance_id}",
        "partition_by": partition_fields,
    }


def _LogCatalogSection_Get(
    metadata: dict[str, Any], schema: dict[str, Any], name: str
) -> Any:
    declared = metadata.get(name, schema.get(name, {}))
    if declared:
        return declared
    if name == "event_catalog":
        return {
            key: value
            for key, value in schema.items()
            if key.endswith("_event") and isinstance(value, dict)
        }
    return {}


def _LogSource_Render(model: ProjectModel) -> str:
    rows = []
    for stream in CompactLogStreams_Get(model):
        rows.append(
            f"    {{{stream.record}, {1 if stream.enabled else 0}U, "
            f"{stream.decimation}U, {stream.period_us}UL,\n"
            f"     SSLOG_STREAM_POLICY_{stream.policy}}}"
        )
    body = ",\n".join(rows)
    layout = {
        'FLIGHT_LOG_RECORD_EVENT': ('event', False),
        'FLIGHT_LOG_RECORD_STATS': ('stats', False),
        'FLIGHT_LOG_RECORD_ESTIMATOR': ('estimator', True),
        'FLIGHT_LOG_RECORD_SYSTEM_CONFIG': ('system_config', False),
        'FLIGHT_LOG_RECORD_PURE_INS': ('pure_ins', False),
        'FLIGHT_LOG_RECORD_KF6_DIAGNOSTIC': ('kf6_diagnostic', True),
        'FLIGHT_LOG_RECORD_KF6_FULL_P': ('kf6_full_p', True),
        'FLIGHT_LOG_RECORD_POWER': ('power', False),
        'FLIGHT_LOG_RECORD_HEALTH': ('health', False),
        'FLIGHT_LOG_RECORD_TELEMETRY_DIAG': ('telemetry_diagnostic', False),
        'FLIGHT_LOG_RECORD_INITIAL_STATE': ('initial_state', False),
        'FLIGHT_LOG_RECORD_GNSS_NATIVE': ('gnss_native', False),
        'FLIGHT_LOG_RECORD_BARO_NATIVE': ('baro_native', False),
        'FLIGHT_LOG_RECORD_MAG_NATIVE': ('mag_native', False),
        'FLIGHT_LOG_RECORD_INERTIAL_INCREMENT': ('inertial_increment', False),
        'FLIGHT_LOG_RECORD_GNSS_MEASUREMENT': ('gnss_measurement', True),
        'FLIGHT_LOG_RECORD_BARO_MEASUREMENT': ('baro_measurement', True),
        'FLIGHT_LOG_RECORD_IMU_CORRECTED': ('imu_corrected', False),
        'FLIGHT_LOG_RECORD_CALIBRATION_RESULT': ('calibration_result', False),
        'FLIGHT_LOG_RECORD_ALIGNMENT_RESULT': ('alignment_result', False),
        'FLIGHT_LOG_RECORD_MISSION_CONFIG': ('mission_config', False),
        'FLIGHT_LOG_RECORD_DEVICE_DESCRIPTOR': ('device_descriptor', False),
        'FLIGHT_LOG_RECORD_ALGORITHM_DESCRIPTOR': ('algorithm_descriptor', False),
        'FLIGHT_LOG_RECORD_LOG_STREAM_DESCRIPTOR': ('stream_descriptor', False),
        'FLIGHT_LOG_RECORD_DECODER_PROFILE_DESCRIPTOR': ('decoder_profile_descriptor', False),
        'FLIGHT_LOG_RECORD_ESTIMATOR_STEP': ('estimator_step', True),
        'FLIGHT_LOG_RECORD_GNSS_RECOVERY': ('gnss_recovery', True),
        'FLIGHT_LOG_RECORD_LANDING_DIAGNOSTIC': ('landing_diagnostic', False),
        'FLIGHT_LOG_RECORD_ESKF15_STATE': ('eskf15_state', False),
        'FLIGHT_LOG_RECORD_ESKF15_FULL_P_PART': ('eskf15_full_p_part', False),
        'FLIGHT_LOG_RECORD_ESKF15_INITIAL_STATE': ('eskf15_initial_state', True),
        'FLIGHT_LOG_RECORD_ESKF15_INITIAL_P_PART': ('eskf15_initial_p_part', True),
        'FLIGHT_LOG_RECORD_ESKF15_MEASUREMENT': ('eskf15_measurement', True),
        'FLIGHT_LOG_RECORD_ESKF15_BODY_INPUT': ('eskf15_body_input', True),
        'FLIGHT_LOG_RECORD_NAV_QUALITY': ('navigation_quality', True),
        'FLIGHT_LOG_RECORD_ALIGNMENT_EVIDENCE': ('alignment_evidence', False),
        'FLIGHT_LOG_RECORD_MISSION_SNAPSHOT_IDENTITY': ('mission_snapshot_identity', False),
        'FLIGHT_LOG_RECORD_MAG_CALIBRATION_IDENTITY': ('mag_calibration_identity', False),
        'FLIGHT_LOG_RECORD_SF6_STATE': ('sf6_state', True),
        'FLIGHT_LOG_RECORD_SF6_MEASUREMENT': ('sf6_measurement', True),
    }
    proofs = []
    for stream in CompactLogStreams_Get(model):
        if stream.enabled:
            member, estimator = layout[stream.record]
            slot = "SYSTEM_LOG_ESTIMATOR_SLOT_SIZE" if estimator else "SYSTEM_LOG_RECORD_SLOT_SIZE"
            proofs.append(f'_Static_assert(offsetof(FlightLogRecord, payload) + sizeof(((FlightLogRecord *)0)->payload.{member}) <= {slot}, "{stream.record} does not fit its queue");')
    proof_text = "\n".join(proofs)
    supported = (sorted(SF6_MINIMAL_RECORDS) if model.build.logging_profile == "sf6_minimal" else sorted(layout))
    supported = [record for record in supported if FeatureTier_LogRecordAllowed(model, record)]
    cases = "\n".join(
        f"        case {record}: return (uint8_t)(offsetof(FlightLogRecord, payload) + "
        f"sizeof(((FlightLogRecord *)0)->payload.{layout[record][0]}) <= "
        f"{'SYSTEM_LOG_ESTIMATOR_SLOT_SIZE' if layout[record][1] else 'SYSTEM_LOG_RECORD_SLOT_SIZE'});"
        for record in supported) + "\n" + "\n".join(
            f"        case {record}: return 0U;" for record in sorted(set(layout) - set(supported)))
    return f"""#include "project_log_config.h"

{AUTOGEN_C_COMMENT}

#include <stddef.h>
#include "sslog_protocol.h"
#include "system_user_config.h"

{proof_text}

static const SystemLogStreamConfig s_project_log_streams[] =
{{
{body}
}};

_Static_assert((sizeof(s_project_log_streams) /
                sizeof(s_project_log_streams[0])) == SSLOG_RECORD_COUNT,
               "project log stream count mismatch");

uint8_t ProjectLogConfig_RecordSupported(FlightLogRecordType type)
{{
    switch (type)
    {{
{cases}
        default: return 0U;
    }}
}}

uint16_t ProjectLogConfig_StreamCountGet(void)
{{
    return (uint16_t)(sizeof(s_project_log_streams) /
                      sizeof(s_project_log_streams[0]));
}}

const SystemLogStreamConfig *ProjectLogConfig_StreamByIndexGet(
    uint16_t index)
{{
    return (index < ProjectLogConfig_StreamCountGet()) ?
        &s_project_log_streams[index] : NULL;
}}
"""


def _DescriptorSymbol_Get(device_class: str, instance_id: int) -> str:
    token = device_class.removeprefix("SYSTEM_DEVICE_CLASS_")
    aliases = {
        "BAROMETER": "BARO",
        "HARDWARE_QUATERNION": "ATTITUDE",
        "MAGNETOMETER": "MAG",
        "MISSION_ACTION": "ACTION",
    }
    token = aliases.get(token, token)
    if re.fullmatch(r"[A-Z][A-Z0-9_]*", token) is None:
        raise ValueError(f"Invalid device descriptor class token: {device_class}")
    return f"PROJECT_DESCRIPTOR_ID_{token}_{instance_id}"


def _DeviceDescriptorEntries_Get(
    model: ProjectModel, catalog: PluginCatalog
) -> list[dict[str, Any]]:
    catalog = catalog.ProjectView_Get(model)
    selected_instances: dict[str, list[str]] = {}
    for instance in model.device_instances:
        selected_instances.setdefault(instance.plugin, []).append(instance.instance_id)
    entries: list[dict[str, Any]] = []
    for component_id in model.ComponentIds_Get():
        manifest = catalog.Component_Get(component_id)
        raw_entries = manifest.metadata.get("device_descriptors", [])
        if not isinstance(raw_entries, list):
            raise ValueError(
                f"Component {component_id} device_descriptors must be an array"
            )
        instance_ids: tuple[str, ...] = ("",)
        if manifest.component_type == "device":
            instance_ids = tuple(selected_instances.get(component_id, ()))
        for source_instance_id in instance_ids:
            instance_manifest = (
                catalog.InstanceIdComponent_Get(source_instance_id)
                if source_instance_id else manifest
            )
            raw_entries = instance_manifest.metadata.get("device_descriptors", [])
            if source_instance_id and instance_manifest.instance_resource_binding is not None:
                accessor = instance_manifest.instance_resource_binding.accessor
                source_instance_index = sum(
                    1 for previous in instance_ids[:instance_ids.index(source_instance_id)]
                    if catalog.InstanceIdComponent_Get(previous).instance_resource_binding
                    is not None
                    and catalog.InstanceIdComponent_Get(
                        previous
                    ).instance_resource_binding.accessor == accessor
                )
            else:
                source_instance_index = (
                    instance_ids.index(source_instance_id) if source_instance_id else 0
                )
            for raw_entry in raw_entries:
                if not isinstance(raw_entry, dict):
                    raise ValueError(
                        f"Component {component_id} device descriptor is invalid"
                    )
                entry = dict(raw_entry)
                if not FeatureTier_DescriptorActive(model, catalog, source_instance_id, str(entry.get("class", ""))):
                    continue
                # The first release retains implementations and schema, but
                # exposes no magnetic endpoint, calibration or storage target.
                if entry.get("class") == "SYSTEM_DEVICE_CLASS_MAGNETOMETER":
                    continue
                entry["_component_id"] = component_id
                entry["_source_instance_id"] = source_instance_id
                entry["_source_instance_index"] = source_instance_index
                physical_symbol = str(entry.get("physical_device_id", ""))
                if len(instance_ids) > 1 and instance_ids.index(source_instance_id) > 0:
                    physical_symbol = (
                        f"{physical_symbol}_{instance_ids.index(source_instance_id)}"
                    )
                entry["physical_device_id"] = physical_symbol
                entries.append(entry)
    entries.sort(
        key=lambda entry: (
            int(entry.get("order", 0)),
            str(entry["_component_id"]),
            str(entry["_source_instance_id"]),
            str(entry.get("class", "")),
        )
    )
    used_instances: dict[str, set[int]] = {}
    for descriptor_id, entry in enumerate(entries, start=1):
        device_class = str(entry.get("class", ""))
        used = used_instances.setdefault(device_class, set())
        requested = entry.get("instance")
        if isinstance(requested, int) and requested >= 0 and requested not in used:
            instance_id = requested
        else:
            instance_id = 0
            while instance_id in used:
                instance_id += 1
        if instance_id > 255:
            raise ValueError(f"Too many instances for device class {device_class}")
        used.add(instance_id)
        physical_id = str(entry.get("physical_device_id", ""))
        if re.fullmatch(
            r"PROJECT_PHYSICAL_DEVICE_ID_[A-Z0-9_]+", physical_id
        ) is None:
            raise ValueError(
                f"Component {entry['_component_id']} has an invalid physical device id"
            )
        entry["_descriptor_id"] = descriptor_id
        entry["_instance_id"] = instance_id
        entry["_descriptor_symbol"] = _DescriptorSymbol_Get(
            device_class, instance_id
        )
    primary_by_class: dict[str, str] = {}
    resolution = CapabilityResolution_Resolve(model, catalog)
    for route in resolution.routes:
        device_class = _CapabilityDeviceClass_Get(route.requirement.capability)
        if device_class and device_class not in primary_by_class:
            primary_by_class[device_class] = route.provider.instance_id
    entries_by_class: dict[str, list[dict[str, Any]]] = {}
    for entry in entries:
        entries_by_class.setdefault(str(entry.get("class", "")), []).append(entry)
    for device_class, class_entries in entries_by_class.items():
        if len(class_entries) <= 1:
            continue
        primary_instance = primary_by_class.get(
            device_class, str(class_entries[0].get("_source_instance_id", ""))
        )
        for entry in class_entries:
            flag_tokens = [
                token.strip()
                for token in str(entry.get("flags", "0U")).split("|")
                if token.strip()
                and token.strip() != "SYSTEM_DESCRIPTOR_FLAG_PRIMARY"
            ]
            if str(entry.get("_source_instance_id", "")) == primary_instance:
                flag_tokens.append("SYSTEM_DESCRIPTOR_FLAG_PRIMARY")
            entry["flags"] = " | ".join(flag_tokens) if flag_tokens else "0U"
    return entries


def _PhysicalDeviceDefinitions_Get(
    catalog: PluginCatalog,
    descriptor_entries: list[dict[str, Any]] | None = None,
) -> tuple[tuple[str, int], ...]:
    orders: dict[str, int] = {"PROJECT_PHYSICAL_DEVICE_ID_NONE": -1}
    for manifest in catalog.All_Get():
        entries = manifest.metadata.get("device_descriptors", [])
        if not isinstance(entries, list):
            continue
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            symbol = entry.get("physical_device_id")
            if not isinstance(symbol, str) or re.fullmatch(
                r"PROJECT_PHYSICAL_DEVICE_ID_[A-Z0-9_]+", symbol
            ) is None:
                continue
            orders[symbol] = min(orders.get(symbol, 0x7FFFFFFF), int(entry.get("order", 0)))
    for entry in descriptor_entries or ():
        symbol = entry.get("physical_device_id")
        if not isinstance(symbol, str) or re.fullmatch(
            r"PROJECT_PHYSICAL_DEVICE_ID_[A-Z0-9_]+", symbol
        ) is None:
            raise ValueError("Generated physical-device symbol is invalid")
        orders.setdefault(symbol, 0x40000000 + int(entry["_descriptor_id"]))
    symbols = sorted(
        orders,
        key=lambda symbol: (
            0 if symbol == "PROJECT_PHYSICAL_DEVICE_ID_NONE" else 1,
            orders[symbol],
            symbol,
        ),
    )
    return tuple((symbol, value) for value, symbol in enumerate(symbols))


def _DeviceInstancesHeader_Render(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    core = catalog.Component_Get(model.core)
    template_path = (
        core.package_root
        / "templates"
        / "generated"
        / "project_device_instances.h"
    )
    if not template_path.is_file():
        raise ValueError("Core plugin has no generated device-instance facade header")
    template = template_path.read_text(encoding="utf-8")
    start_marker = "#define PROJECT_PHYSICAL_DEVICE_ID_NONE"
    end_marker = "uint8_t ProjectDeviceInstance_CountGet"
    start = template.find(start_marker)
    end = template.find(end_marker, start)
    if start < 0 or end < 0:
        raise ValueError("Device-instance facade header template markers changed")
    descriptors = _DeviceDescriptorEntries_Get(model, catalog)
    physical_definitions = _PhysicalDeviceDefinitions_Get(catalog, descriptors)
    physical_width = max(len(symbol) for symbol, _value in physical_definitions)
    physical_rows = "\n".join(
        f"#define {symbol:<{physical_width}} {value}U"
        for symbol, value in physical_definitions
    )
    descriptor_width = max(
        (len(str(entry["_descriptor_symbol"])) for entry in descriptors),
        default=1,
    )
    descriptor_rows = "\n".join(
        f"#define {entry['_descriptor_symbol']:<{descriptor_width}} "
        f"{entry['_descriptor_id']}U"
        for entry in descriptors
    )
    selected_counts: dict[str, int] = {}
    for entry in descriptors:
        device_class = str(entry["class"])
        selected_counts[device_class] = selected_counts.get(device_class, 0) + 1
    bound_values: list[tuple[str, int]] = []
    for device_class, (_label, bound_macro) in _DEVICE_FACADE_CLASSES.items():
        selected_count = selected_counts.get(device_class, 0)
        pattern = rf"#define\s+{re.escape(bound_macro)}\s+(\d+)U"
        match = re.search(pattern, template)
        if match is None:
            raise ValueError(
                f"Device-instance facade bound is missing: {bound_macro}"
            )
        bound_values.append((bound_macro, max(1, selected_count) if model.build.compact_mode
                             else max(int(match.group(1)), selected_count)))
    bound_width = max(len(macro) for macro, _value in bound_values)
    bound_rows = "\n".join(
        f"#define {macro:<{bound_width}} {value}U"
        for macro, value in bound_values
    )
    replacement = (
        physical_rows
        + "\n\n"
        + descriptor_rows
        + "\n\n"
        + "/* Static bounds for per-capability runtime state. */\n"
        + bound_rows
        + "\n\n"
    )
    rendered = template[:start] + replacement + template[end:]
    return rendered.replace(
        "#define __PROJECT_DEVICE_INSTANCES_H\n",
        "#define __PROJECT_DEVICE_INSTANCES_H\n\n" + AUTOGEN_C_COMMENT + "\n",
        1,
    )


def _DeviceInstancesSource_Render(
    model: ProjectModel, catalog: PluginCatalog
) -> str:
    core = catalog.Component_Get(model.core)
    template_path = (
        core.package_root
        / "templates"
        / "generated"
        / "project_device_instances.c"
    )
    if not template_path.is_file():
        raise ValueError("Core plugin has no generated device-instance facade source")
    template = template_path.read_text(encoding="utf-8")
    rendered = _DeviceInstanceSwitches_Render(template, model, catalog)
    return rendered.replace(
        '#include "project_device_instances.h"\n',
        '#include "project_device_instances.h"\n\n' + AUTOGEN_C_COMMENT + "\n",
        1,
    )


_DEVICE_FACADE_CLASSES: dict[str, tuple[str, str]] = {
