    "SYSTEM_DEVICE_CLASS_GNSS": ("Gnss", "PROJECT_GNSS_INSTANCE_COUNT_MAX"),
    "SYSTEM_DEVICE_CLASS_BAROMETER": (
        "Barometer",
        "PROJECT_BAROMETER_INSTANCE_COUNT_MAX",
    ),
    "SYSTEM_DEVICE_CLASS_MAGNETOMETER": (
        "Magnetometer",
        "PROJECT_MAGNETOMETER_INSTANCE_COUNT_MAX",
    ),
    "SYSTEM_DEVICE_CLASS_HARDWARE_QUATERNION": (
        "Attitude",
        "PROJECT_ATTITUDE_INSTANCE_COUNT_MAX",
    ),
    "SYSTEM_DEVICE_CLASS_TELEMETRY": (
        "Telemetry",
        "PROJECT_TELEMETRY_INSTANCE_COUNT_MAX",
    ),
    "SYSTEM_DEVICE_CLASS_POWER": (
        "Power",
        "PROJECT_POWER_INSTANCE_COUNT_MAX",
    ),
}


def _DeviceInstanceSwitches_Render(
    template: str, model: ProjectModel, catalog: PluginCatalog
) -> str:
    descriptors = _DeviceDescriptorEntries_Get(model, catalog)
    endpoints: dict[str, list[tuple[dict[str, Any], dict[str, Any]]]] = {
        device_class: [] for device_class in _DEVICE_FACADE_CLASSES
    }
    headers: set[str] = set()
    for entry in descriptors:
        device_class = str(entry.get("class", ""))
        if device_class not in endpoints:
            continue
        source_id = str(entry["_source_instance_id"])
        manifest = (
            catalog.InstanceIdComponent_Get(source_id)
            if source_id else catalog.Component_Get(str(entry["_component_id"]))
        )
        bindings = manifest.metadata.get("device_instance_bindings")
        binding = bindings.get(device_class) if isinstance(bindings, dict) else None
        if not isinstance(binding, dict):
            raise ValueError(
                f"Device plugin {manifest.component_id} has no direct binding "
                f"for {device_class}"
            )
        allowed = {
            "function_prefix",
            "headers",
            "operations",
            "pass_instance",
            "unsupported_operations",
        }
        if not set(binding).issubset(allowed):
            raise ValueError(
                f"Device plugin {manifest.component_id} direct binding has "
                "unknown fields"
            )
        prefix = binding.get("function_prefix")
        if not isinstance(prefix, str) or re.fullmatch(
            r"[A-Za-z_][A-Za-z0-9_]*", prefix
        ) is None:
            raise ValueError(
                f"Device plugin {manifest.component_id} direct binding prefix "
                "is invalid"
            )
        raw_headers = binding.get("headers", [])
        if not isinstance(raw_headers, list) or not all(
            isinstance(header, str)
            and re.fullmatch(r"[A-Za-z0-9_./-]+\.h", header)
            for header in raw_headers
        ):
            raise ValueError(
                f"Device plugin {manifest.component_id} direct binding headers "
                "are invalid"
            )
        headers.update(raw_headers)
        endpoints[device_class].append((entry, binding))
    rendered = template
    for device_class, (label, _bound_macro) in _DEVICE_FACADE_CLASSES.items():
        class_endpoints = sorted(
            endpoints[device_class], key=lambda item: int(item[0]["_instance_id"])
        )
        actual_ids = [int(entry["_instance_id"]) for entry, _binding in class_endpoints]
        if actual_ids != list(range(len(actual_ids))):
            raise ValueError(
                f"Generated {device_class} endpoints are not contiguous"
            )
        function_pattern = re.compile(
            rf"SystemDeviceResult Project{label}Instance_([A-Za-z0-9_]+)\("
        )
        operations = tuple(
            match.group(1) for match in function_pattern.finditer(rendered)
        )
        if not operations:
            raise ValueError(f"Device-instance facade class is missing: {label}")
        for operation in operations:
            rendered = _DeviceInstanceFunctionSwitch_Render(
                rendered, label, operation, class_endpoints
            )
    if headers:
        anchor = '#include "silverstar_assert.h"\n'
        if anchor not in rendered:
            raise ValueError("Device-instance facade include anchor changed")
        additions = "".join(f'#include "{header}"\n' for header in sorted(headers))
        rendered = rendered.replace(anchor, anchor + additions, 1)
    return rendered


def _DeviceInstanceFunctionSwitch_Render(
    source: str,
    label: str,
    operation: str,
    endpoints: list[tuple[dict[str, Any], dict[str, Any]]],
) -> str:
    function_marker = f"SystemDeviceResult Project{label}Instance_{operation}("
    function_start = source.find(function_marker)
    if function_start < 0:
        raise ValueError(f"Device-instance facade function is missing: {function_marker}")
    switch_start = source.find("switch (instance_id)", function_start)
    next_function = source.find("\nSystemDeviceResult ", function_start + 1)
    if switch_start < 0 or (next_function >= 0 and switch_start > next_function):
        raise ValueError(f"Device-instance facade switch is missing: {function_marker}")
    brace_start = source.find("{", switch_start)
    brace_end = _CBlockEnd_Find(source, brace_start)
    original = source[brace_start + 1 : brace_end]
    argument_match = re.search(
        r"case\s+0U:\s*return\s+[A-Za-z_][A-Za-z0-9_]*\((.*?)\);",
        original,
        re.DOTALL,
    )
    if argument_match is None:
        if ((label, operation) in (("Gnss", "RecoveryBusyGet"), ("Imu", "RecoveryPreparedGet")) and
                "case 0U: return SYSTEM_DEVICE_UNSUPPORTED;" in original):
            arguments = "busy" if label == "Gnss" else "prepared"
        else:
            raise ValueError(
                f"Device-instance facade reference case changed: {function_marker}"
            )
    else:
        arguments = " ".join(argument_match.group(1).split())
    cases: list[str] = []
    for entry, binding in endpoints:
        unsupported = binding.get("unsupported_operations", [])
        if not isinstance(unsupported, list) or not all(
            isinstance(value, str) for value in unsupported
        ):
            raise ValueError("Device-instance unsupported operation list is invalid")
        instance_id = int(entry["_instance_id"])
        if operation in unsupported:
            cases.append(
                f"        case {instance_id}U: return SYSTEM_DEVICE_UNSUPPORTED;"
            )
            continue
        overrides = binding.get("operations", {})
        if not isinstance(overrides, dict) or not all(
            isinstance(key, str) and isinstance(value, str)
            for key, value in overrides.items()
        ):
            raise ValueError("Device-instance operation overrides are invalid")
        if (label == "Telemetry" and operation in ("SendControl", "TxResultGet")
                and operation not in overrides):
            cases.append(f"        case {instance_id}U: return SYSTEM_DEVICE_UNSUPPORTED;")
            continue
        if (label == "Gnss" and operation == "RecoveryBusyGet"
                and operation not in overrides):
            cases.append(f"        case {instance_id}U: return SYSTEM_DEVICE_UNSUPPORTED;")
            continue
        if (label == "Imu" and operation == "RecoveryPreparedGet"
                and operation not in overrides):
            cases.append(f"        case {instance_id}U: return SYSTEM_DEVICE_UNSUPPORTED;")
            continue
        symbol = overrides.get(
            operation, f"{binding['function_prefix']}_{operation}"
        )
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", symbol) is None:
            raise ValueError("Device-instance direct function symbol is invalid")
        pass_instance = binding.get("pass_instance", False)
        if not isinstance(pass_instance, bool):
            raise ValueError("Device-instance pass_instance must be boolean")
        call_arguments = arguments
        if pass_instance:
            source_index = int(entry["_source_instance_index"])
            call_arguments = (
                f"{source_index}U, {arguments}" if arguments else f"{source_index}U"
            )
        cases.append(
            f"        case {instance_id}U: return {symbol}({call_arguments});"
        )
    body = "\n" + "\n".join(cases)
    if cases:
        body += "\n"
    body += "        default: return SYSTEM_DEVICE_NOT_PRESENT;\n    "
    return source[: brace_start + 1] + body + source[brace_end:]


def _CBlockEnd_Find(source: str, brace_start: int) -> int:
    if brace_start < 0 or source[brace_start] != "{":
        raise ValueError("Generated C block start is missing")
    depth = 0
    for index in range(brace_start, len(source)):
        if source[index] == "{":
            depth += 1
        elif source[index] == "}":
            depth -= 1
            if depth == 0:
                return index
    raise ValueError("Generated C block is unterminated")


def _MetadataSource_Render(model: ProjectModel, catalog: PluginCatalog) -> str:
    device_entries = _DeviceDescriptorEntries_Get(model, catalog)
    algorithm_entries: list[dict[str, Any]] = []
    for component_id in model.ComponentIds_Get():
        metadata = catalog.Component_Get(component_id).metadata
        algorithm_entries.extend(metadata.get("algorithm_descriptors", []))
    algorithm_entries.sort(key=lambda entry: int(entry["order"]))
    device_rows = []
    for entry in device_entries:
        device_rows.append(
            "    { "
            f"{entry['_descriptor_symbol']}, {entry['physical_device_id']},\n"
            f"      {entry['class']}, {entry['_instance_id']}U, "
            f"{int(entry.get('driver_id', 1))}U,\n"
            f"      {entry['flags']},\n"
            f"      {entry['capability']}, {entry['rate']},\n"
            f"      {entry['driver_hash']}, {entry['name_hash']} }}"
        )
    algorithm_rows = []
    for descriptor_id, entry in enumerate(algorithm_entries, start=1):
        algorithm_rows.append(
            "    { "
            f"{descriptor_id}U, {entry['class']}, {int(entry.get('instance', 0))}U,\n"
            f"      (uint16_t){entry['algorithm']},\n"
            f"      {entry['flags']},\n"
            f"      SILVERSTAR_PROJECT_CONFIG_DIGEST ^ 0x{descriptor_id:04X}0000UL, "
            f"{entry['name_hash']} }}"
        )
    digest = ProjectDigest_Get(model)
    device_rows_text = ",\n".join(device_rows)
    algorithm_rows_text = ",\n".join(algorithm_rows)
    snapshot_assert = f"""#include "sslog_records.h"
_Static_assert((1U + sizeof(s_device_descriptors) / sizeof(s_device_descriptors[0]) +
               sizeof(s_algorithm_descriptors) / sizeof(s_algorithm_descriptors[0]) +
               SSLOG_RECORD_COUNT + 4U + PROJECT_MAGNETOMETER_INSTANCE_COUNT_MAX) <= 65535U,
               "Snapshot descriptor count exceeds its owner cursor capacity");""" if model.build.compact_mode and model.protocols.get("logging") is not None else ""
    return f"""#include "system_descriptor_if.h"

{AUTOGEN_C_COMMENT}

#include <stddef.h>

#include "project_device_instances.h"
#include "silverstar_assert.h"
#include "system_capabilities.h"
#include "system_user_config.h"

#define SILVERSTAR_PROJECT_CONFIG_DIGEST 0x{digest:08X}UL

static const SystemDeviceDescriptor s_device_descriptors[] =
{{
{device_rows_text}
}};

static const SystemAlgorithmDescriptor s_algorithm_descriptors[] =
{{
{algorithm_rows_text}
}};

_Static_assert((sizeof(s_device_descriptors) /
                sizeof(s_device_descriptors[0])) <=
               SYSTEM_DESCRIPTOR_DEVICE_COUNT_MAX,
               "target device descriptor table exceeds interface bound");
_Static_assert((sizeof(s_algorithm_descriptors) /
                sizeof(s_algorithm_descriptors[0])) <=
               SYSTEM_DESCRIPTOR_ALGORITHM_COUNT_MAX,
               "target algorithm descriptor table exceeds interface bound");
{snapshot_assert}

uint16_t SystemDescriptor_DeviceCountGet(void)
{{
    uint16_t count = 0U;
    uint16_t index;

    for (index = 0U;
         index < (sizeof(s_device_descriptors) /
                  sizeof(s_device_descriptors[0]));
         index++)
    {{
        if ((s_device_descriptors[index].flags &
             SYSTEM_DESCRIPTOR_FLAG_ENABLED) != 0U)
        {{
            count++;
        }}
    }}
    return count;
}}

SystemDeviceResult SystemDescriptor_DeviceGet(
    uint16_t index, SystemDeviceDescriptor *descriptor)
{{
    uint16_t enabled_index = 0U;
    uint16_t table_index;

    if (descriptor == NULL)
    {{
        return SYSTEM_DEVICE_INVALID_ARGUMENT;
    }}
    SILVERSTAR_ASSERT_OBJECT(descriptor, SystemDeviceDescriptor,
        SILVERSTAR_ASSERT_MODULE_GENERATED);
    for (table_index = 0U;
         table_index < (sizeof(s_device_descriptors) /
                        sizeof(s_device_descriptors[0]));
         table_index++)
    {{
        if ((s_device_descriptors[table_index].flags &
             SYSTEM_DESCRIPTOR_FLAG_ENABLED) == 0U)
        {{
            continue;
        }}
        if (enabled_index == index)
        {{
            *descriptor = s_device_descriptors[table_index];
            return SYSTEM_DEVICE_OK;
        }}
        enabled_index++;
    }}
    return SYSTEM_DEVICE_INVALID_ARGUMENT;
}}

uint8_t SystemDescriptor_DeviceClassInstanceCountGet(
    SystemDeviceClass device_class)
{{
    uint8_t count = 0U;
    uint16_t index;

    for (index = 0U;
         index < (sizeof(s_device_descriptors) /
                  sizeof(s_device_descriptors[0]));
         index++)
    {{
        if (((s_device_descriptors[index].flags &
              SYSTEM_DESCRIPTOR_FLAG_ENABLED) != 0U) &&
            (s_device_descriptors[index].device_class == device_class))
        {{
            count++;
        }}
    }}
    return count;
}}

SystemDeviceResult SystemDescriptor_DeviceFind(
    SystemDeviceClass device_class, uint8_t instance_id,
    SystemDeviceDescriptor *descriptor)
{{
    uint16_t index;

    if (descriptor == NULL) {{ return SYSTEM_DEVICE_INVALID_ARGUMENT; }}
    SILVERSTAR_ASSERT_OBJECT(descriptor, SystemDeviceDescriptor,
        SILVERSTAR_ASSERT_MODULE_GENERATED);
    for (index = 0U;
         index < (sizeof(s_device_descriptors) /
                  sizeof(s_device_descriptors[0]));
         index++)
    {{
        if (((s_device_descriptors[index].flags &
              SYSTEM_DESCRIPTOR_FLAG_ENABLED) != 0U) &&
            (s_device_descriptors[index].device_class == device_class) &&
            (s_device_descriptors[index].instance_id == instance_id))
        {{
            *descriptor = s_device_descriptors[index];
            return SYSTEM_DEVICE_OK;
        }}
    }}
    return SYSTEM_DEVICE_NOT_PRESENT;
}}

uint16_t SystemDescriptor_AlgorithmCountGet(void)
{{
    return (uint16_t)(sizeof(s_algorithm_descriptors) /
                      sizeof(s_algorithm_descriptors[0]));
}}

SystemDeviceResult SystemDescriptor_AlgorithmGet(
    uint16_t index, SystemAlgorithmDescriptor *descriptor)
{{
    if ((descriptor == NULL) ||
        (index >= SystemDescriptor_AlgorithmCountGet()))
    {{
        return SYSTEM_DEVICE_INVALID_ARGUMENT;
    }}
    *descriptor = s_algorithm_descriptors[index];
    return SYSTEM_DEVICE_OK;
}}

uint32_t SystemDescriptor_ConfigDigestGet(void)
{{
    return SILVERSTAR_PROJECT_CONFIG_DIGEST;
}}
"""


