\t@echo "FCCG_PROGRESS|LINK_DONE|$@"
\t@echo "FCCG_PROGRESS|SIZE_BEGIN|$@"
\t$(SZ) $@
\t@echo "FCCG_PROGRESS|SIZE_DONE|$@"

$(BUILD_ROOT)/%.hex: $(BUILD_ROOT)/%.elf
\t@echo "FCCG_PROGRESS|HEX_BEGIN|$@"
