\t@echo "FCCG_PROGRESS|CLEAN_ALL|PLAN|3"
\t@echo "FCCG_PROGRESS|CLEAN_ALL|BEGIN|1|3|build/FCCG"
\tpowershell -NoProfile -Command "if (Test-Path -LiteralPath 'build/FCCG') {{ Remove-Item -LiteralPath 'build/FCCG' -Recurse -Force -ErrorAction Stop }}"
\t@echo "FCCG_PROGRESS|CLEAN_ALL|DONE|1|3|build/FCCG"
