def _MakeSymbol_Get(value: str) -> str:
    return "_".join(
        part for part in re.split(r"[^A-Za-z0-9]+", value.upper()) if part
    )


def _TargetManifest_Render(
    model: ProjectModel, catalog: PluginCatalog, graph: SourceGraph
) -> str:
    flags = (" \\" + "\n" + "                    ").join(graph.mcu_flags)
    specs = " ".join(graph.specs)
    libraries = " ".join(graph.libraries)
    device_symbols = {
        catalog.Component_Get(instance.plugin).component_class: _MakeSymbol_Get(
            catalog.Component_Get(instance.plugin).name
        )
        for instance in model.device_instances
    }
    platform_backend = _MakeSymbol_Get(
        catalog.Component_Get(model.mcu).component_class
    )
    board_manifest = catalog.Component_Get(model.board) if model.board else None
    board_symbol = (
        board_manifest.metadata.get("build_symbol", board_manifest.name)
        if board_manifest is not None
        else "CUSTOM_STM32"
    )
    board_profile = _MakeSymbol_Get(str(board_symbol))
    return f"""# AUTO-GENERATED BY SILVERSTAR_FCCG. DO NOT EDIT.
# Target flags are resolved from the selected MCU plugin.
BUILD_MANIFESTS += Targets/{model.build.target_profile}/target.mk

IMU_DRIVER := {device_symbols.get('imu', '')}
GNSS_DRIVER := {device_symbols.get('gnss', '')}
TELEMETRY_DRIVER := {device_symbols.get('telemetry', '')}
PLATFORM_BACKEND := {platform_backend}
BOARD_PROFILE := {board_profile}

TOOLCHAIN_PREFIX ?= {graph.toolchain_prefix}
TARGET_MCU_FLAGS := {flags}
TARGET_LDSCRIPT := {graph.linker_script}
TARGET_SPECS := {specs}
TARGET_LIBS := {libraries}
"""


def _VsCodeTasks_Render(model: ProjectModel) -> str:
    def task(label: str, args: list[str], matcher: Any = "$gcc", group: Any = None) -> dict[str, Any]:
        value: dict[str, Any] = {
            "label": label,
            "type": "shell",
            "command": model.build.make_command,
            "args": args,
            "problemMatcher": matcher,
        }
        if group is not None:
            value["group"] = group
        return value

    debug = [f"TARGET_PROFILE={model.build.target_profile}", "CONFIG=Debug"]
    release = [f"TARGET_PROFILE={model.build.target_profile}", "CONFIG=Release"]
    tasks = [
        task(
            "SilverStar: Build Release",
            [*release, "all"],
            group={"kind": "build", "isDefault": True},
        ),
        task("SilverStar: Build Debug", [*debug, "all"]),
        task("SilverStar: Clean FCCG Build Outputs", ["clean"], []),
        task("SilverStar: Clean All Build Outputs", ["clean-all"], []),
        task("SilverStar: Host tests", ["host-tests"]),
        task("SilverStar: Architecture check", ["architecture-check"], []),
        task("SilverStar: Power of Ten check", ["power10-check"], []),
        task("SilverStar: Static analysis", [*release, "static-analysis"]),
        task("SilverStar: Artifact check", [*release, "artifact-check"]),
    ]
    return json.dumps({"version": "2.0.0", "tasks": tasks}, indent=4) + "\n"


def _EnvironmentTemplate_Read(
    environment: PluginManifest, relative: str
) -> str:
    template_root = (environment.package_root / "templates" / "reference").resolve()
    path = template_root.joinpath(*relative.split("/")).resolve()
    try:
        path.relative_to(template_root)
    except ValueError as error:
        raise ValueError("Development-environment template escaped its package") from error
    if not path.is_file() or path.is_symlink():
        raise ValueError(f"Development-environment reference template is missing: {relative}")
    return path.read_text(encoding="utf-8")


def _ReferenceWorkspace_Get(environment: PluginManifest) -> dict[str, Any]:
    value = json.loads(
        _EnvironmentTemplate_Read(
            environment, "Flight_Controller0.5.code-workspace"
        )
    )
    if not isinstance(value, dict):
        raise ValueError("Reference VS Code workspace must be an object")
    return value


def _VsCodeSettings_Render(environment: PluginManifest) -> str:
    settings = _ReferenceWorkspace_Get(environment).get("settings")
    if not isinstance(settings, dict):
        raise ValueError("Reference VS Code workspace has no settings object")
    return json.dumps(settings, ensure_ascii=False, indent=4) + "\n"


def _VsCodeExtensions_Render(environment: PluginManifest) -> str:
    extensions = _ReferenceWorkspace_Get(environment).get("extensions")
    if not isinstance(extensions, dict):
        raise ValueError("Reference VS Code workspace has no extensions object")
    return json.dumps(extensions, ensure_ascii=False, indent=4) + "\n"


def _VsCodeWorkspace_Render(
    model: ProjectModel, environment: PluginManifest
) -> str:
    value = _ReferenceWorkspace_Get(environment)
    value["folders"] = [{"name": model.identity.name, "path": "."}]
    return json.dumps(value, ensure_ascii=False, indent=4) + "\n"


def _EideTarget_Render(
    reference_body: str,
    graph: SourceGraph,
    *,
    optimization: str,
    layout_defines: tuple[str, ...] = (),
) -> str:
    defines = "\n".join(
        f"        - {value}" for value in (*graph.defines, *layout_defines)
    )
    includes = "\n".join(f"        - {value}" for value in graph.include_dirs)
    exclude_block = (
        "    excludeList:\n"
        + "\n".join(f"      - {value}" for value in graph.exclude_sources)
        + "\n"
        if graph.exclude_sources
        else "    excludeList: []\n"
    )
    forced_flags = " ".join(f"-include {value}" for value in graph.forced_includes)
    libraries = " ".join(graph.libraries)
    body = re.sub(
        r"(?ms)^      defineList:\n.*?(?=^      incList:)",
        f"      defineList:\n{defines}\n",
        reference_body,
        count=1,
    )
    body = re.sub(
        r"(?ms)^      incList:\n.*?(?=^      libList:)",
        f"      incList:\n{includes}\n",
        body,
        count=1,
    )
    body = re.sub(
        r"(?ms)^    excludeList:.*?(?=^    settings:)",
        exclude_block,
        body,
        count=1,
    )
    replacements = (
        (r"(?m)^(            C_FLAGS:).*$", rf"\1 {forced_flags}"),
        (r"(?m)^(            optimization:).*$", rf"\1 {optimization}"),
        (r"(?m)^(            LIB_FLAGS:).*$", rf"\1 {libraries}"),
        (
            r"(?m)^(        scatterFilePath:).*$",
            rf"\1 {graph.linker_script}",
        ),
    )
    for pattern, replacement in replacements:
        body, count = re.subn(pattern, replacement, body, count=1)
        if count != 1:
            raise ValueError(f"Reference EIDE target field changed: {pattern}")
    return body.rstrip()


def _Eide_Render(
    model: ProjectModel, graph: SourceGraph, environment: PluginManifest
) -> str:
    reference = _EnvironmentTemplate_Read(environment, ".eide/eide.yml")
    if "-mcpu=cortex-m3" in graph.mcu_flags:
        reference = reference.replace("cpuType: Cortex-M4", "cpuType: Cortex-M3")
        reference = reference.replace("floatingPointHardware: single", "floatingPointHardware: none")
        reference = reference.replace("$float-abi-type: hard", "$float-abi-type: soft")
    target_marker = "targets:\n  Debug:\n"
    if target_marker not in reference:
        raise ValueError("Reference EIDE template has no Debug target")
    prefix, reference_target = reference.split(target_marker, 1)
    virtual_set = set(graph.virtual_sources)
    source_dirs = tuple(
        dict.fromkeys(
            str(Path(source).parent).replace("\\", "/")
            for source in graph.sources
            if source not in virtual_set
        )
    )
    source_directories = "\n".join(f"  - {value}" for value in source_dirs)
    virtual_files = "\n".join(
        f"    - path: {value}"
        for value in (*graph.virtual_sources, *graph.asm_sources)
    )
    prefix, count = re.subn(
        r"(?m)^name:.*$",
        f"name: {json.dumps(model.identity.name, ensure_ascii=False)}",
        prefix,
        count=1,
    )
    if count != 1:
        raise ValueError("Reference EIDE project name field changed")
    prefix = re.sub(
        r"(?ms)^srcDirs:\n.*?(?=^virtualFolder:)",
        f"srcDirs:\n{source_directories}\n",
        prefix,
        count=1,
    )
    prefix = re.sub(
        r"(?ms)^(  files:)\n.*?(?=^  folders:)",
        rf"\1\n{virtual_files}\n",
        prefix,
        count=1,
    )
    prefix = re.sub(
        r"(?m)^outDir:.*$",
        lambda _match: (
            f"outDir: build\\FCCG\\{model.build.target_profile}\\EIDE"
        ),
        prefix,
        count=1,
    )
    prefix = re.sub(
        r"(?m)^(  uid:).*$",
        rf"\1 {ProjectDigest_Get(model):032x}",
        prefix,
        count=1,
    )
    # Make applies the selected layout after the common source graph. EIDE's
    # compiler view must carry the same saved configuration without baking it
    # into that graph (which would break explicit Make layout overrides).
    layout_defines = {
        "legacy": (),
        "auto": ("SILVERSTAR_MEMORY_LAYOUT_AUTO=1",),
        "eskf_window_sram": ("SILVERSTAR_MEMORY_LAYOUT_ESKF_WINDOW_SRAM=1",),
    }[model.build.memory_layout]
    release = _EideTarget_Render(
        reference_target, graph, optimization="level-2", layout_defines=layout_defines
    )
    debug = _EideTarget_Render(
        reference_target, graph, optimization="level-debug", layout_defines=layout_defines
    )
    return (
        "# AUTO-GENERATED BY SILVERSTAR_FCCG.\n"
        "# Structural template copied from the validated read-only firmware.\n"
        f"{prefix.rstrip()}\n"
        "targets:\n"
        f"  Release:\n{release}\n"
        f"  Debug:\n{debug}\n"
    )


def _EideFileOptions_Render(environment: PluginManifest) -> str:
    reference = _EnvironmentTemplate_Read(
        environment, ".eide/files.options.yml"
    )
    marker = "options:\n    Debug:"
    if marker not in reference:
        raise ValueError("Reference EIDE file-options template has no Debug profile")
    return reference.replace(
        marker,
        "options:\n"
        "    Release:\n"
        "        files: {}\n"
        "        virtualPathFiles: {}\n"
        "    Debug:",
        1,
    )


def _Configuration_Render(model: ProjectModel, catalog: PluginCatalog, graph: SourceGraph) -> str:
    lines = [
        f"# {model.identity.name} Configuration",
        "",
        "> AUTO-GENERATED BY SILVERSTAR_FCCG. This human-readable file may be overwritten.",
        "",
        f"- Firmware: `{model.identity.firmware_version}`",
        f"- Build target: `{model.identity.build_target}`",
        f"- Target profile: `{model.build.target_profile}`",
        "- Configurations: `Release` (default), `Debug`",
        f"- Toolchain prefix: `{graph.toolchain_prefix}`",
        f"- MCU: `{model.mcu}`",
        f"- Board: `{catalog.Component_Get(model.board).name if model.board else 'custom hardware'}`",
        f"- Hardware source: `{model.hardware.source_kind}` / `{model.hardware.mode}`",
        f"- Development environment: `{model.development_environment}`",
        "- Authoritative source graph: `Generated/project_sources.mk`",
        f"- EIDE mode: `{model.build.eide_mode}`",
        "",
        "## Components",
        "",
    ]
    for component_id in model.ComponentIds_Get():
        manifest = catalog.Component_Get(component_id)
        lines.append(
            f"- `{manifest.component_type}` / `{manifest.component_class or 'default'}`: "
            f"{manifest.name} `{manifest.version}` (`{component_id}`)"
        )
    lines.extend(("", "## Strategies", ""))
    for slot, component_id in sorted(model.strategies.items()):
        lines.append(f"- `{slot}`: `{component_id or 'None'}`")
    lines.extend(("", "## Modes", ""))
    for slot, selections in sorted(model.modes.items()):
        lines.append(f"- `{slot}`: `{', '.join(selections) if selections else '[]'}`")
    lines.extend(("", "## Mode parameters", ""))
    for slot, options in sorted(model.mode_parameters.items()):
        selected_options = set(model.modes.get(slot, []))
        for option, parameters in sorted(options.items()):
            state = "active" if option in selected_options else "retained / inactive"
            rendered = ", ".join(
                f"{parameter_id}={value}"
                for parameter_id, value in sorted(parameters.items())
            )
            lines.append(f"- `{slot}.{option}` ({state}): `{rendered}`")
    lines.extend(("", "## Protocol profiles", ""))
    protocol_bindings = {
        binding.category: binding
        for binding in ProtocolResolution_Resolve(model, catalog).bindings
    }
    for category, selection in sorted(model.protocols.items()):
        if selection is None:
            lines.append(f"- `{category}`: `None`")
            continue
        profile_id = selection.profile
        display_name = profile_id
        for protocol_id in model.ProtocolComponentIds_Get():
            contribution = catalog.Component_Get(protocol_id).protocol
            if contribution is None:
                continue
            display_name = next(
                (
                    profile.DisplayName_Get("en_US")
                    for profile in contribution.profiles.get(category, ())
                    if profile.profile_id == profile_id
                ),
                display_name,
            )
        binding = protocol_bindings.get(category)
        binding_text = (
            f" → `{binding.binding}` → `{binding.provider_instance}`"
            if binding is not None
            else " → unresolved transport"
        )
        lines.append(
            f"- `{category}`: {display_name} (`{profile_id}`){binding_text}"
        )
    capability_resolution = CapabilityResolution_Resolve(model, catalog)
    lines.extend(("", "## Enabled Device capabilities", ""))
    for instance in model.device_instances:
        capabilities = capability_resolution.EnabledCapabilitiesForInstance_Get(
            instance.instance_id
        )
        lines.append(
            f"- `{instance.instance_id}`: "
            f"`{', '.join(capabilities) if capabilities else '[]'}`"
        )
    lines.extend(("", "## Resource mapping", ""))
    for key, value in sorted(model.resource_assignments.items()):
        lines.append(f"- `{key}` → `{value}`")
    lines.extend(("", "## SSLOG streams", ""))
    if model.protocols.get("logging") is None:
        lines.append("- Logging Protocol disabled; retained stream settings are inactive.")
    for stream in CompactLogStreams_Get(model):
        state = (
            "inactive (configured enabled)"
            if model.protocols.get("logging") is None and stream.enabled
            else "inactive"
            if model.protocols.get("logging") is None
            else "enabled"
            if stream.enabled
            else "disabled"
        )
        lines.append(
            f"- `{stream.record}`: {state}, `{stream.policy}`, "
            f"decimation={stream.decimation}, period_us={stream.period_us}"
        )
    lines.extend(("", "## Hardware provenance", ""))
    lines.extend(
        (
            f"- CubeMX version: `{model.hardware.cubemx_version}`",
            f"- STM32Cube firmware package: `{model.hardware.firmware_package}`",
            f"- HAL/CMSIS source policy: `{model.hardware.hal_cmsis_source_policy}`",
            "- Resource binding fingerprint: "
            f"`{HardwareResourceBindingFingerprint_Get(model, catalog)}`",
        )
    )
    if model.hardware.mode == "custom":
        lines.extend(
            (
                f"- Provider: `{model.hardware.provider}`",
                f"- Imported project: `{model.hardware.source_label}`",
                f"- IOC: `{model.hardware.ioc_file}`",
                f"- Imported MCU: `{model.hardware.mcu}`",
                f"- Snapshot digest: `{model.hardware.source_digest}`",
                "- Verification: custom hardware; not an official SilverStar hardware verification claim",
            )
        )
    else:
        board = catalog.Component_Get(model.board)
        lines.extend(
            (
                f"- Board source kind: `{board.board.source_kind if board.board else 'unknown'}`",
                f"- Verified: `{bool(board.board and board.board.verified)}`",
            )
        )
    lines.extend(("", "## Reference provenance", ""))
    for key, value in sorted(model.reference_provenance.items()):
        lines.append(f"- `{key}`: `{value}`")
    if model.protocols.get("logging") is not None:
        lines.extend(
            (
                "",
                "## Log decoder profile",
                "",
                f"- Package: `{model.log_decoder_profile.relative_path}`",
                f"- Package schema: `{model.log_decoder_profile.package_schema}`",
                f"- Container plugin: `{model.log_decoder_profile.container_plugin_id}`",
                "- Generation profile SHA-256: "
                f"`{model.log_decoder_profile.generation_profile_sha256}`",
                f"- Package SHA-256: `{model.log_decoder_profile.package_sha256}`",
            )
        )
    lines.extend(
        (
            "",
            "## Resolved source graph",
            "",
            f"- C sources: `{len(graph.sources)}`",
            f"- Assembler sources: `{len(graph.asm_sources)}`",
            f"- Include directories: `{len(graph.include_dirs)}`",
            f"- Linker script: `{graph.linker_script}`",
        )
    )
    lines.extend(
        (
            "",
            "## Ownership",
            "",
            "Component payloads are project-owned after first copy and are not overwritten by normal Apply.",
            "Only `Generated/` glue and FCCG project/build metadata are normally regenerated by FCCG.",
            "`HardwareGenerated/` is vendor-owned data and is replaced only after an explicit re-import confirmation.",
            "",
        )
    )
    return "\n".join(lines)


def _GeneratedReadme_Render(model: ProjectModel) -> str:
    decoder_lines = (
