    )
    included_names = (
        "DECODER_PROFILE_DESCRIPTOR",
        "SYSTEM_CONFIG",
        "DEVICE_DESCRIPTOR",
        "LOG_STREAM_DESCRIPTOR",
        "IMU_CORRECTED",
        "GNSS_NATIVE",
