"""Exact mini native PCD input and separately owned classic CDC companion.

This is a bounded software profile, not general C0 or native CubeMX CDC support.
The input project is never edited and the companion contains no HAL/CMSIS,
startup or linker replacement.
"""
from pathlib import Path
import hashlib
import json
import difflib

PART = "STM32C071FBP6"
COMPANION = "silverstar.usb_cdc.stm32c071_mini"
PROFILE = "C071FBP6_MINI_USB_V1"
PREFIX = "HardwareGenerated/C071ClassicCDC/"
_EXPECTED = {
    "companion-manifest.json": "8835f4c76e6ea94ceeccf742ec59665157ddf2a089a4a361ad25b2671afcc6d7",
    "native-profile.json": "5c9ad2ccaae3b0bd4a81c00e5c450610f48c82b7d5958c9587b921be82d29589",
}


def C071Profile_Get(name: str) -> dict:
    if name not in _EXPECTED:
        raise ValueError("unknown C071 profile metadata")
    plugin = Path(__file__).resolve().parents[3] / "plugins/builtin/silverstar_usb_cdc_stm32c071_mini"
    path = plugin / name
    if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest() != _EXPECTED[name]:
        raise ValueError("C071 reviewed profile metadata changed: " + name)
    return json.loads(path.read_text(encoding="utf8"))


def C071Native_Validate(root: Path) -> dict:
    # Publish the effective CDC capability only after validating the actual
    # registered payload, rather than trusting a part number or manifest alone.
    from silverstar_fccg.plugins.manifest import PluginManifest_Load
    plugin = Path(__file__).resolve().parents[3] / "plugins/builtin/silverstar_usb_cdc_stm32c071_mini"
    C071Companion_Validate(PluginManifest_Load(plugin / "plugin.json"))
    profile = C071Profile_Get("native-profile.json")
    if hashlib.sha256((root / "Makefile").read_bytes()).hexdigest() != profile["makefile_sha256"]:
        raise ValueError("C071 native literal build inventory changed")
    iocs = tuple(root.glob("*.ioc"))
    if len(iocs) != 1 or hashlib.sha256(iocs[0].read_bytes()).hexdigest() != profile["ioc_sha256"]:
        raise ValueError("C071 requires the exact reviewed mini IOC profile; other parts/pins/configurations are unsupported")
    actual = {p.relative_to(root).as_posix() for directory in (root / "Core", root / "Drivers")
              for p in directory.rglob("*") if p.is_file()}
    if actual != set(profile["files_sha256"]):
        raise ValueError("C071 native Core/Drivers file inventory differs from reviewed complete input")
    for relative, digest in profile["files_sha256"].items():
        path = root / relative
        if path.is_symlink() or not path.resolve().is_relative_to(root.resolve()):
            raise ValueError("C071 native dependency escapes input: " + relative)
        if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise ValueError("C071 native source/configuration changed: " + relative)
    for relative, key in (("startup_stm32c071xx.s", "startup_sha256"),
                          ("STM32C071XX_FLASH.ld", "linker_sha256")):
        if hashlib.sha256((root / relative).read_bytes()).hexdigest() != profile[key]:
            raise ValueError("C071 native startup/linker identity changed")
    manifest = C071Profile_Get("companion-manifest.json")
    return {"profile": PROFILE, "component": COMPANION, "version": "0.1.1",
            "manifest_sha256": _EXPECTED["companion-manifest.json"],
            "native_profile_sha256": _EXPECTED["native-profile.json"],
            "source_commits": manifest["source_commits"], "vendor_patches": manifest["vendor_patches"],
            "native_project_complete": True, "native_cdc": False,
            "input_kind": "native_pcd_plus_pinned_classic_cdc",
            "support_maturity": "experimental"}


# Package pad identity survives normalization of CubeMX's remapped names.
# PA9/PA10 share the USB pads; PB3..PB6 and PA14/PA15 are shared package pads.
C071_PAD_ALIASES = {
    "16": ("PA11", "PA9"), "17": ("PA12", "PA10"),
    "19": ("PA14", "PA15"), "20": ("PB3", "PB4", "PB5", "PB6"),
}


def C071PadIdentity_Get(ioc: str) -> dict:
    fields = dict(line.split("=", 1) for line in ioc.splitlines() if "=" in line)
    raw = {fields[key]: fields.get(fields[key] + ".Signal", "")
           for key in fields if key.startswith("Mcu.Pin") and key[7:].isdigit()}
    return {pad: {"aliases": list(aliases), "selected_raw": [name for name in raw
                if name in aliases or name.startswith((aliases[0] + " [", aliases[0] + "-"))],
                "normalized": aliases[0]} for pad, aliases in C071_PAD_ALIASES.items()}


def C071Companion_Validate(component) -> dict:
    if component.component_id != COMPANION or component.source != "builtin" or component.version != "0.1.1":
        raise ValueError("C071 companion must be its exact registered builtin revision")
    manifest = C071Profile_Get("companion-manifest.json")
    actual = {p.relative_to(component.payload_root).as_posix() for p in component.PayloadFiles_Get()}
    if actual != set(manifest["files_sha256"]):
        raise ValueError("C071 companion file inventory changed")
    for relative, digest in manifest["files_sha256"].items():
        path = component.payload_root / relative
        if path.is_symlink() or not path.resolve().is_relative_to(component.payload_root.resolve()):
            raise ValueError("C071 companion dependency escapes payload")
        if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise ValueError("C071 companion source changed: " + relative)
    for patch in manifest["vendor_patches"]:
        original = component.payload_root / patch["original_path"]
        derived = component.payload_root / patch["derived_path"]
        expected = ''.join(difflib.unified_diff(
            original.read_text(encoding='utf8').splitlines(keepends=True),
            derived.read_text(encoding='utf8').splitlines(keepends=True),
            fromfile=patch["original_path"], tofile=patch["derived_path"]))
        if expected.encode() != (component.payload_root / patch["patch_path"]).read_bytes():
            raise ValueError("C071 companion patch is not reproducible: " + patch["id"])
        for field in ("original", "derived", "patch"):
            if manifest["files_sha256"][patch[field + "_path"]] != patch[field + "_sha256"]:
                raise ValueError("C071 companion patch provenance differs: " + patch["id"])
    return manifest


def C071GroundModel_Validate(model, catalog) -> None:
    from dataclasses import asdict
    from silverstar_fccg.project.model import GroundRadioConfigurations_Get
    ground = model.ground_target
    hardware = ground.hardware
    if (ground.mcu != "silverstar.mcu.stm32c071fbp6" or hardware.mcu != PART or
            hardware.mode != "custom" or ground.board or ground.pc_interface != "usb_cdc" or
            hardware.hal_cmsis_source_policy != "imported_tree_authoritative"):
        raise ValueError("C071 mini requires exact MCU, complete native custom input and USB CDC")
    radios = GroundRadioConfigurations_Get(ground)
    if (model.air_link.radio_family != "sx128x" or len(radios) != 1 or
            radios[0].plugin != "silverstar.device.telemetry.sx1281" or
            radios[0].module_variant != "e28_2g4m12sx" or radios[0].instance_id != "radio0"):
        raise ValueError("C071 mini requires its single reviewed E28 SX1281 radio")
    expected = {"radio0:" + role: value for role, value in {
        "radio_bus": "SPI1", "radio_nss": "RADIO_NSS", "radio_reset": "RADIO_RESET",
        "radio_busy": "RADIO_BUSY", "radio_dio1": "RADIO_DIO1", "time": "SYSTEM_TIME"}.items()}
    if ground.resource_assignments != expected:
        raise ValueError("C071 mini fixed radio/resource binding changed")
    companion = hardware.inventory.get("c071_companion", {})
    if (companion.get("profile") != PROFILE or companion.get("component") != COMPANION or companion.get("version") != "0.1.1" or
            companion.get("manifest_sha256") != _EXPECTED["companion-manifest.json"] or
            companion.get("native_profile_sha256") != _EXPECTED["native-profile.json"] or
            companion.get("native_cdc") is not False or
            companion.get("input_kind") != "native_pcd_plus_pinned_classic_cdc"):
        raise ValueError("C071 registered companion provenance missing or changed; reimport")
    profile = C071Profile_Get("native-profile.json")
    def digest(value):
        return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
    ignore = {"ground_cubemx_base", "c071_companion", "package_pad_identity", "native_usb_cdc", "usb_cdc"}
    inventory = {k: v for k, v in hardware.inventory.items() if k not in ignore}
    if hardware.inventory.get("package_pad_identity") != profile["package_pad_identity"]:
        raise ValueError("C071 shared physical pad identity changed; reimport")
    if (digest([asdict(r) for r in hardware.resources]) != profile["resources_sha256"] or
            digest(inventory) != profile["native_inventory_sha256"]):
        raise ValueError("C071 native resource/pin/clock inventory changed; reimport")
    for name, value in profile["effective_build"].items():
        actual = getattr(hardware, name)
        if (list(actual) if isinstance(actual, tuple) else actual) != value:
            raise ValueError("C071 effective source ownership changed: " + name)
    hashes = hardware.inventory.get("ground_cubemx_base", {}).get("artifact_hashes", {})
    expected_hashes = dict(profile["files_sha256"])
    expected_hashes.update({"Makefile": profile["makefile_sha256"],
        hardware.ioc_file: profile["ioc_sha256"],
        "startup_stm32c071xx.s": profile["startup_sha256"],
        "STM32C071XX_FLASH.ld": profile["linker_sha256"]})
    if any(hashes.get(path) != digest for path, digest in expected_hashes.items()):
        raise ValueError("C071 stored native identity differs from reviewed complete input")
    C071Companion_Validate(catalog.Component_Get(COMPANION))

src\\silverstar_fccg\\hardware\\cubemx.p.source:
from __future__ import annotations

import hashlib
import json
import re
import shutil
from collections.abc import Callable
from dataclasses import dataclass, replace
from pathlib import Path

from silverstar_fccg.core.workspace import WorkspacePolicy, WorkspacePolicyError
from silverstar_fccg.core.errors import FccgError
from silverstar_fccg.hardware.inventory import HardwareInventory, CubeMxInventory_Parse
from silverstar_fccg.project.model import HardwareConfiguration, HardwareResource


class CubeMxImportError(FccgError):
    pass


@dataclass(frozen=True, slots=True)
class CubeMxImportResult:
    hardware: HardwareConfiguration
    snapshot_root: Path
    peripherals: tuple[str, ...]
    warnings: tuple[str, ...]
    inventory: HardwareInventory


class CubeMxImporter:
    """Validate and copy a generated CubeMX project without executing it."""

    MAX_FILE_COUNT = 20_000
    MAX_TOTAL_SIZE = 512 * 1024 * 1024
    _IGNORED_DIRECTORIES = frozenset(
        {".git", ".svn", "build", "debug", "release", "cmake-build-debug"}
    )
    _ALLOWED_SUFFIXES = frozenset(
        {
            ".c",
            ".h",
            ".s",
            ".ioc",
            ".ld",
            ".txt",
            ".md",
            ".xml",
            ".json",
            ".properties",
            ".project",
            ".mxproject",
        }
    )

    def __init__(self, policy: WorkspacePolicy, cache_root: Path | None = None) -> None:
        self.policy = policy
        self.cache_root = self.policy.Path_Resolve(
            cache_root or (self.policy.root / ".fccg" / "hardware_imports")
        )

    def Project_Import(
        self,
        input_path: Path,
        *,
        expected_mcu: str = "",
        provider_id: str = "silverstar.hardware_provider.stm32_cubemx",
        risk_acknowledged: bool = False,
        progress_callback: Callable[[int, int, str, bool], None] | None = None,
        target: str = "flight",
    ) -> CubeMxImportResult:
        if target not in {"flight", "ground"}:
            raise CubeMxImportError("CubeMX import target must be flight or ground")
        phases = (
            "read_ioc",
            "parse_peripherals",
            "parse_gpio_dma_irq",
            "build_hardware_inventory",
            "conflict_check",
            "save_snapshot",
        )

        def progress(current: int, done: bool) -> None:
            if progress_callback is not None:
                progress_callback(
                    current, len(phases), phases[current - 1], done
                )

        progress(1, False)
        root, ioc_path = self._Input_Resolve(input_path)
        if target == "ground" and len(tuple(root.glob("*.ioc"))) != 1:
            raise CubeMxImportError("Ground CubeMX project must contain exactly one root .ioc file")
        if target == "ground":
            # Reject aliases before inventory readers open generated sources.
            for path in root.rglob("*"):
                if path.is_symlink() or not path.resolve().is_relative_to(root):
                    raise CubeMxImportError("Ground dependency escapes the copied project: " + str(path))
        ioc_text = self._Text_Read(ioc_path)
        progress(1, True)

        progress(2, False)
        actual_mcu = self._Mcu_Get(ioc_text)
        peripherals = self._Peripherals_Get(ioc_text)
        progress(2, True)

        progress(3, False)
        generated_files = self._GeneratedFiles_Get(root)
        inventory = CubeMxInventory_Parse(
            ioc_text, generated_files=generated_files
        )
        progress(3, True)

        progress(4, False)
        resources = inventory.HardwareResources_Get()
        if target == "ground":
            resources = tuple(replace(resource, metadata={
                **resource.metadata, "pins": {"dm": "PA11", "dp": "PA12"},
                "interrupt": "USB_LP_CAN1_RX0_IRQn" if actual_mcu == "STM32F103C8T6" else "OTG_FS_IRQn",
            }) if resource.kind == "usb_cdc" else resource for resource in resources)
        capabilities = tuple(
            sorted({f"peripheral.{resource.kind}" for resource in resources})
        )
        warnings = self._Warnings_Get(ioc_text, peripherals, inventory)
        progress(4, True)

        progress(5, False)
        if expected_mcu and not self._Mcu_Matches(actual_mcu, expected_mcu):
            raise CubeMxImportError(
                f"CubeMX MCU {actual_mcu!r} does not match selected MCU {expected_mcu!r}"
            )
        self._RtosConflict_Validate(root, ioc_text)
        generated_layout = (root / "Core" / "Src" / "main.c").is_file()
        if target == "ground" and not generated_layout:
            raise CubeMxImportError("Ground requires a generated CubeMX project containing its .ioc and Core/Src/main.c; Generate Code before importing")
        if generated_layout or (root / "Core").exists() or (root / "Drivers").exists():
            self._GeneratedLayout_Validate(root)
        source_files = self._SourceFiles_Get(root, ground=target == "ground")
        ground_inputs = None
        if target == "ground":
            from silverstar_fccg.hardware.cubemx_ground import GroundCubeInputs_Get, GroundUsbConfiguration_Validate

            try:
                ground_inputs = GroundCubeInputs_Get(root, actual_mcu)
                GroundUsbConfiguration_Validate(root, ioc_text, actual_mcu)
            except ValueError as error:
                raise CubeMxImportError(str(error)) from error
            except (OSError, UnicodeError) as error:
                raise CubeMxImportError(f"Cannot read required Ground CubeMX input: {error}; Generate Code with copied libraries and reimport") from error
        digest = self._SnapshotDigest_Get(root, source_files)
        progress(5, True)

        progress(6, False)
        snapshot_root = self._Snapshot_Store(
            root,
            source_files,
            digest,
            cubemx_version=inventory.cubemx_version,
            firmware_package=inventory.firmware_package,
        )
        prefix = "HardwareGenerated/STM32CubeMX"
        source_roots = (
            root / "Core" / "Src",
            root / "FATFS" / "App",
            root / "FATFS" / "Target",
            root / "USB_DEVICE" / "App",
            root / "USB_DEVICE" / "Target",
            root / "Middlewares" / "ST" / "STM32_USB_Device_Library" / "Core" / "Src",
            root / "Middlewares" / "ST" / "STM32_USB_Device_Library" / "Class" / "CDC" / "Src",
        )
        build_sources = tuple(
            f"{prefix}/{path.relative_to(root).as_posix()}"
            for source_root in source_roots
            if source_root.is_dir()
            for path in sorted(source_root.glob("*.c"))
            if path.name.casefold() not in {"freertos.c", "sysmem.c"}
        )
        if not generated_layout:
            warnings = (*warnings, "CubeMX .ioc imported; generate CubeMX project sources before firmware generation")
        # The imported tree is retained as an auditable snapshot, but only
        # Controlled application/board-generated code and the CubeMX USB
        # Device middleware enter the source graph. HAL, CMSIS, startup and
        # linker ownership remains with the matched Platform plugin.
        include_dirs = tuple(
            f"{prefix}/{relative}"
            for relative in (
                "Core/Inc", "FATFS/App", "FATFS/Target",
                "USB_DEVICE/App", "USB_DEVICE/Target",
                "Middlewares/ST/STM32_USB_Device_Library/Core/Inc",
                "Middlewares/ST/STM32_USB_Device_Library/Class/CDC/Inc",
            )
            if (root / Path(*relative.split("/"))).is_dir()
        )
        inventory_data = inventory.Dictionary_Get()
        if ground_inputs is not None:
            build_sources = ground_inputs.sources
            include_dirs = ground_inputs.includes
            inventory_data["ground_cubemx_base"] = {
                "format_version": 1,
                "mcu_flags": list(ground_inputs.flags),
                "required_irq_handlers": list(ground_inputs.irq_handlers),
                "build_manifest": "Makefile",
                "artifact_hashes": {
                    "README.md": hashlib.sha256(self._SnapshotReadme_Get().encode("utf8")).hexdigest(),
                    **{path.relative_to(root).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
                       for path in source_files if path.relative_to(root).as_posix() != "README.md"},
                },
            }
        hardware = HardwareConfiguration(
            mode="custom",
            source_kind="manual_import",
            provider=provider_id,
            snapshot_id=digest,
            ioc_file=ioc_path.relative_to(root).as_posix(),
            mcu=actual_mcu,
            cubemx_version=inventory.cubemx_version,
            firmware_package=inventory.firmware_package,
            capabilities=capabilities,
            inventory=inventory_data,
            resources=resources,
            build_sources=build_sources,
            include_dirs=include_dirs,
            asm_sources=ground_inputs.assembly if ground_inputs else (),
            defines=ground_inputs.defines if ground_inputs else (),
            linker_script=ground_inputs.linker if ground_inputs else "",
            hal_cmsis_source_policy="imported_tree_authoritative" if ground_inputs else "",
            source_digest=digest,
            source_label=root.name,
            risk_acknowledged=risk_acknowledged,
        )
        progress(6, True)
        return CubeMxImportResult(
            hardware=hardware,
            snapshot_root=snapshot_root,
            peripherals=peripherals,
            warnings=warnings,
            inventory=inventory,
        )

    def SnapshotRoot_Get(self, snapshot_id: str) -> Path:
        if not re.fullmatch(r"[0-9a-f]{64}", snapshot_id):
            raise CubeMxImportError("Invalid CubeMX snapshot id")
        root = self.policy.Path_Resolve(
            self.cache_root / snapshot_id / "STM32CubeMX", allow_root=False
        )
        if not root.is_dir():
            raise CubeMxImportError(f"CubeMX snapshot is unavailable: {snapshot_id}")
        return root

    def _Input_Resolve(self, input_path: Path) -> tuple[Path, Path]:
        selected = input_path.resolve(strict=False)
        if selected.is_symlink():
            raise CubeMxImportError("CubeMX input symlinks are not accepted")
        if selected.is_file():
            if selected.suffix.casefold() != ".ioc":
                raise CubeMxImportError("Select a CubeMX .ioc file or generated project directory")
            root = selected.parent.resolve()
            ioc_path = selected
        elif selected.is_dir():
            root = selected.resolve()
            ioc_files = sorted(root.glob("*.ioc"))
            if len(ioc_files) != 1:
                raise CubeMxImportError(
                    "CubeMX project directory must contain exactly one root .ioc file"
                )
            ioc_path = ioc_files[0]
        else:
            raise CubeMxImportError(f"CubeMX input does not exist: {selected}")
        return root, ioc_path

    @staticmethod
    def _Text_Read(path: Path) -> str:
        try:
            return path.read_text(encoding="utf-8-sig")
        except (OSError, UnicodeError) as error:
            raise CubeMxImportError(f"Cannot read CubeMX .ioc file: {error}") from error

    @classmethod
    def _GeneratedFiles_Get(cls, root: Path) -> dict[str, str]:
        files: dict[str, str] = {}
        for relative_root in (
            "Core/Src", "Core/Inc", "FATFS/App", "FATFS/Target",
            "USB_DEVICE/App", "USB_DEVICE/Target",
        ):
            directory = root / Path(*relative_root.split("/"))
            if not directory.is_dir():
                continue
            for path in sorted(directory.glob("*")):
                if path.is_file() and path.suffix.casefold() in {".c", ".h"}:
                    files[path.relative_to(root).as_posix()] = cls._Text_Read(path)
        return files

    @staticmethod
    def _Mcu_Get(ioc_text: str) -> str:
        values: dict[str, str] = {}
        for line in ioc_text.splitlines():
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            values[key.strip()] = value.strip()
        for key in ("Mcu.CPN", "Mcu.Name", "ProjectManager.DeviceId"):
            if values.get(key):
                return values[key]
        raise CubeMxImportError("CubeMX .ioc does not declare an MCU model")

    @staticmethod
    def _Mcu_Matches(actual: str, expected: str) -> bool:
        actual_token = re.sub(r"[^A-Z0-9]", "", actual.upper())
        expected_token = re.sub(r"[^A-Z0-9]", "", expected.upper())
        if actual_token == expected_token:
            return True
        pattern = "".join("[A-Z0-9]" if char == "X" else re.escape(char) for char in actual_token)
        return bool(re.fullmatch(pattern, expected_token)) or (
            len(actual_token) >= 11 and expected_token.startswith(actual_token[:11])
        )

    @staticmethod
    def _RtosConflict_Validate(root: Path, ioc_text: str) -> None:
        if re.search(r"(?i)(FREERTOS|CMSIS[-_ ]?RTOS)", ioc_text):
            raise CubeMxImportError(
                "SilverStar uses its official FreeRTOS component; CubeMX FreeRTOS/CMSIS-RTOS2 cannot be imported"
            )
        conflict_paths = (
            root / "Middlewares" / "Third_Party" / "FreeRTOS",
            root / "Middlewares" / "Third_Party" / "FreeRTOS-Kernel",
            root / "Core" / "Src" / "freertos.c",
        )
        if any(path.exists() for path in conflict_paths):
            raise CubeMxImportError(
                "CubeMX project contains a second FreeRTOS/CMSIS-RTOS2 implementation"
            )

    @staticmethod
    def _GeneratedLayout_Validate(root: Path) -> None:
        required_directories = (
            root / "Core" / "Inc",
            root / "Core" / "Src",
            root / "Drivers" / "CMSIS",
        )
        missing = [path.relative_to(root).as_posix() for path in required_directories if not path.is_dir()]
        hal_candidates = tuple((root / "Drivers").glob("STM32*xx_HAL_Driver"))
        if not hal_candidates:
            missing.append("Drivers/STM32*xx_HAL_Driver")
        if missing:
            raise CubeMxImportError(
                "CubeMX generated project is incomplete: " + ", ".join(missing)
            )
        if not any(root.rglob("startup_*.s")):
            raise CubeMxImportError("CubeMX project has no startup assembler file")
        if not any(root.rglob("*.ld")):
            raise CubeMxImportError("CubeMX project has no linker script")

    def _SourceFiles_Get(self, root: Path, *, ground: bool = False) -> tuple[Path, ...]:
        files: list[Path] = []
        total_size = 0
        for path in root.rglob("*"):
            relative = path.relative_to(root)
            if any(part.casefold() in self._IGNORED_DIRECTORIES for part in relative.parts):
                continue
            if path.is_symlink():
                raise CubeMxImportError(f"CubeMX project symlink rejected: {relative.as_posix()}")
            if not path.is_file():
                continue
            if path.suffix.casefold() not in self._ALLOWED_SUFFIXES and not (ground and relative.as_posix() == "Makefile"):
                continue
            try:
                self.policy.RelativePath_Validate(relative.as_posix())
            except WorkspacePolicyError as error:
                raise CubeMxImportError(
                    f"CubeMX project contains an unsafe path: {relative.as_posix()}"
                ) from error
            total_size += path.stat().st_size
            files.append(path)
            if len(files) > self.MAX_FILE_COUNT:
                raise CubeMxImportError("CubeMX project contains too many files")
            if total_size > self.MAX_TOTAL_SIZE:
                raise CubeMxImportError("CubeMX project is too large to import")
        return tuple(sorted(files, key=lambda item: item.relative_to(root).as_posix().casefold()))

    @staticmethod
    def _SnapshotDigest_Get(root: Path, files: tuple[Path, ...]) -> str:
        digest = hashlib.sha256()
        for path in files:
            relative = path.relative_to(root).as_posix()
            digest.update(relative.encode("utf-8"))
            digest.update(b"\0")
            digest.update(hashlib.sha256(path.read_bytes()).digest())
        return digest.hexdigest()

    def _Snapshot_Store(
        self,
        root: Path,
        files: tuple[Path, ...],
        digest: str,
        *,
        cubemx_version: str,
        firmware_package: str,
    ) -> Path:
        destination = self.policy.Path_Resolve(
            self.cache_root / digest / "STM32CubeMX", allow_root=False
        )
        if destination.is_dir():
            return destination
        stage = self.policy.StagingDirectory_Create("cubemx-")
        staged_snapshot = stage / "STM32CubeMX"
        try:
            for source in files:
                relative = source.relative_to(root)
                target = staged_snapshot / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, target)
            readme = self._SnapshotReadme_Get()
            (staged_snapshot / "README.md").write_text(readme, encoding="utf-8", newline="\n")
            metadata = {
                "format_version": 0,
                "provider": "stm32_cubemx",
                "source_label": root.name,
                "source_digest": digest,
                "cubemx_version": cubemx_version,
                "firmware_package": firmware_package,
            }
            (stage / "import.json").write_text(
                json.dumps(metadata, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            destination.parent.parent.mkdir(parents=True, exist_ok=True)
            if destination.parent.exists():
                self.policy.Tree_Remove(destination.parent)
            self.policy.Path_Replace(stage, destination.parent)
            return destination
        except Exception:
            if stage.exists():
                self.policy.Tree_Remove(stage)
            raise

    @staticmethod
    def _SnapshotReadme_Get() -> str:
        return (
            "# HardwareGenerated / STM32CubeMX\n\n"
            "This directory comes from STM32CubeMX. It is not SilverStar generic "
            "Platform or Device source. Regenerating hardware may replace this directory.\n\n"
            "After any hardware change, rebuild and repeat clock, DMA, interrupt, GPIO, "
            "electrical-level and power validation. Vendor-generated code is a controlled "
            "Power-of-Ten deviation; SilverStar adapters and generated glue remain in scope.\n"
        )

    @staticmethod
    def _Peripherals_Get(ioc_text: str) -> tuple[str, ...]:
        values = {
            match.group(1).strip()
            for match in re.finditer(r"(?m)^Mcu\.IP\d+=(.+)$", ioc_text)
        }
        return tuple(sorted(values, key=CubeMxImporter._NaturalKey_Get))

    @staticmethod
    def _NaturalKey_Get(value: str) -> tuple[str, int, str]:
        match = re.search(r"(\d+)$", value)
        return (
            re.sub(r"\d+$", "", value),
            int(match.group(1)) if match else -1,
            value,
        )

    @staticmethod
    def _Resources_Get(
        ioc_text: str, peripherals: tuple[str, ...]
    ) -> tuple[HardwareResource, ...]:
        del peripherals
        return CubeMxInventory_Parse(ioc_text).HardwareResources_Get()

    @staticmethod
    def _Warnings_Get(
        ioc_text: str,
        peripherals: tuple[str, ...],
        inventory: HardwareInventory | None = None,
    ) -> tuple[str, ...]:
        warnings: list[str] = []
        for label, pattern in (
            ("DMA", r"(?i)DMA"),
            ("NVIC", r"(?i)NVIC"),
            ("GPIO", r"(?i)GPIO"),
        ):
            if not re.search(pattern, ioc_text):
                warnings.append(f"CubeMX configuration does not expose {label} settings")
        for family in ("UART", "SPI", "I2C", "ADC"):
            if not any(item.startswith((family, "USART" if family == "UART" else family)) for item in peripherals):
                warnings.append(f"No {family} peripheral is enabled")
        if inventory is not None:
            warnings.extend(inventory.issues)
        return tuple(warnings)

