from __future__ import annotations

import math
import re
from dataclasses import dataclass

from silverstar_fccg.app.version import (
    SILVERSTAR_BUILD_ID,
    SILVERSTAR_CORE_COMPONENT_ID,
    SILVERSTAR_PLATFORM_VERSION,
